-- === FILE: update_autoassign_schema.sql === --
-- ============================================================ -- ChronosWork â€” ActualizaciÃ³n de Esquema: AsignaciÃ³n AutomÃ¡tica -- Ejecutar en: Supabase SQL Editor -- ============================================================  -- â”€â”€ 1. Modificaciones en tabla "areas" â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ ALTER TABLE areas   ADD COLUMN IF NOT EXISTS cobertura_minima_diaria INT DEFAULT 1,   ADD COLUMN IF NOT EXISTS cobertura_maxima_diaria INT DEFAULT 10,   ADD COLUMN IF NOT EXISTS cobertura_por_turno JSONB DEFAULT '{}'::jsonb;  -- â”€â”€ 2. Modificaciones en tabla "employees" â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ -- 2.1 AÃ±adir columnas de contrato y descansos ALTER TABLE employees   ADD COLUMN IF NOT EXISTS tipo_contrato VARCHAR(20) DEFAULT 'POR_HORAS' CHECK (tipo_contrato IN ('SALARIO_FIJO', 'POR_HORAS')),   ADD COLUMN IF NOT EXISTS dias_descanso_semana INT DEFAULT 1 CHECK (dias_descanso_semana IN (1, 2));  -- 2.2 AÃ±adir turno_predeterminado_id (requiere que la tabla shift_templates exista) ALTER TABLE employees   ADD COLUMN IF NOT EXISTS turno_predeterminado_id UUID REFERENCES shift_templates(id) ON DELETE SET NULL;  CREATE INDEX IF NOT EXISTS idx_employees_turno_predeterminado ON employees(turno_predeterminado_id);  -- Opcional: Actualizar datos existentes (si es necesario) -- UPDATE areas SET cobertura_minima_diaria = 1, cobertura_maxima_diaria = 10 WHERE cobertura_minima_diaria IS NULL; -- UPDATE employees SET tipo_contrato = 'POR_HORAS', dias_descanso_semana = 1 WHERE tipo_contrato IS NULL;

-- === FILE: update_wfm_groups.sql === --
-- ActualizaciÃ³n para agregar group_id a los slots de demanda WFM -- Ejecutar en: Supabase SQL Editor  ALTER TABLE area_demand_slots ADD COLUMN IF NOT EXISTS group_id UUID;  -- Para los registros existentes (si los hay), asignamos su propio ID como group_id UPDATE area_demand_slots SET group_id = id WHERE group_id IS NULL;  -- Hacer que la columna sea obligatoria a partir de ahora ALTER TABLE area_demand_slots ALTER COLUMN group_id SET NOT NULL;

-- === FILE: area_demand_schema.sql === --
-- ============================================================ -- ChronosWork â€” Curva de Demanda Horaria por Ãrea -- Ejecutar en: Supabase SQL Editor -- Prerequisito: areas_schema.sql y update_autoassign_schema.sql ya aplicados -- ============================================================  -- â”€â”€ TABLA: area_demand_slots â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ -- Almacena cuÃ¡ntos asesores se necesitan por franja horaria, por dÃ­a de semana, -- para cada Ã¡rea. Reemplaza el nÃºmero fijo cobertura_minima_diaria cuando el -- Ã¡rea tiene operaciÃ³n 24/7 o picos variables. -- -- Ejemplo de filas para un lunes en un call center: --   area_id | day_of_week | start_hour | end_hour | required_staff --   <uuid>  |      1      |     0      |    5     |       2         â† madrugada --   <uuid>  |      1      |     5      |    7     |       5         â† apertura --   <uuid>  |      1      |     7      |    13    |      15         â† pico maÃ±ana --   <uuid>  |      1      |    13      |    19    |      12         â† pico tarde --   <uuid>  |      1      |    19      |    24    |       6         â† cierre -- ============================================================  CREATE TABLE IF NOT EXISTS area_demand_slots (   id             UUID PRIMARY KEY DEFAULT uuid_generate_v4(),   group_id       UUID NOT NULL,   tenant_id      UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,   area_id        UUID NOT NULL REFERENCES areas(id)   ON DELETE CASCADE,   day_of_week    INT  NOT NULL CHECK (day_of_week BETWEEN 1 AND 7),  -- 1=Lun â€¦ 7=Dom   start_hour     INT  NOT NULL CHECK (start_hour BETWEEN 0 AND 23),   end_hour       INT  NOT NULL CHECK (end_hour   BETWEEN 1 AND 24),  -- 24 = medianoche   required_staff INT  NOT NULL DEFAULT 1 CHECK (required_staff >= 0),   created_at     TIMESTAMPTZ DEFAULT NOW(),    -- No se pueden solapar franjas del mismo dÃ­a/Ã¡rea (restricciÃ³n de unicidad simple)   UNIQUE (area_id, day_of_week, start_hour),   CONSTRAINT check_hours CHECK (end_hour > start_hour) );  CREATE INDEX IF NOT EXISTS idx_demand_slots_tenant  ON area_demand_slots(tenant_id); CREATE INDEX IF NOT EXISTS idx_demand_slots_area    ON area_demand_slots(area_id); CREATE INDEX IF NOT EXISTS idx_demand_slots_day     ON area_demand_slots(area_id, day_of_week);  -- â”€â”€ RLS â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ ALTER TABLE area_demand_slots ENABLE ROW LEVEL SECURITY;  DO $$ BEGIN    IF NOT EXISTS (     SELECT 1 FROM pg_policies     WHERE tablename = 'area_demand_slots' AND policyname = 'demand_slots_select'   ) THEN     CREATE POLICY "demand_slots_select" ON area_demand_slots       FOR SELECT USING (tenant_id = auth_tenant_id() OR is_platform_admin());   END IF;    IF NOT EXISTS (     SELECT 1 FROM pg_policies     WHERE tablename = 'area_demand_slots' AND policyname = 'demand_slots_insert'   ) THEN     CREATE POLICY "demand_slots_insert" ON area_demand_slots       FOR INSERT WITH CHECK (tenant_id = auth_tenant_id());   END IF;    IF NOT EXISTS (     SELECT 1 FROM pg_policies     WHERE tablename = 'area_demand_slots' AND policyname = 'demand_slots_update'   ) THEN     CREATE POLICY "demand_slots_update" ON area_demand_slots       FOR UPDATE USING (tenant_id = auth_tenant_id());   END IF;    IF NOT EXISTS (     SELECT 1 FROM pg_policies     WHERE tablename = 'area_demand_slots' AND policyname = 'demand_slots_delete'   ) THEN     CREATE POLICY "demand_slots_delete" ON area_demand_slots       FOR DELETE USING (tenant_id = auth_tenant_id());   END IF;  END $$;  -- â”€â”€ FUNCIÃ“N HELPER: obtener el requerimiento de personal en una hora dada â”€â”€â”€â”€ -- Ãštil para queries ad-hoc o desde Edge Functions en el futuro. -- Retorna required_staff para (area_id, day_of_week, hora_exacta). -- Si no hay franja configurada para esa hora, retorna NULL. CREATE OR REPLACE FUNCTION get_required_staff_at(   p_area_id    UUID,   p_day        INT,   -- 1=Lun â€¦ 7=Dom   p_hour       INT    -- 0-23 ) RETURNS INT AS $$   SELECT required_staff   FROM area_demand_slots   WHERE area_id    = p_area_id     AND day_of_week = p_day     AND start_hour  <= p_hour     AND end_hour    >  p_hour   LIMIT 1; $$ LANGUAGE sql STABLE SECURITY DEFINER;

-- === FILE: add_labor_limits_areas.sql === --
-- ============================================================ -- ChronosWork â€” MigraciÃ³n: LÃ­mites de jornada personalizables por Ã¡rea -- Ejecutar en: Supabase SQL Editor -- Prerequisito: areas_schema.sql ya aplicado -- ============================================================  -- AÃ±adir campo labor_limits al Ã¡rea -- Almacena overrides del empleador sobre los defaults legales colombianos. -- NULL = usar siempre los defaults de la ley (LEGAL_DEFAULTS_CO en el front). -- Ejemplo de estructura: -- { --   "maxHorasSemanales": 36, --   "minHorasTurno": 4, --   "maxHorasTurno": 8, --   "maxHorasDiarias": 9, --   "minHorasEntreJornadas": 10, --   "diasDescansoSemana": 2 -- } ALTER TABLE areas   ADD COLUMN IF NOT EXISTS labor_limits JSONB DEFAULT NULL;  COMMENT ON COLUMN areas.labor_limits IS   'Override de lÃ­mites de jornada laboral. NULL = defaults legales Colombia (Ley 2101/2021 + Ley 2466/2025).';

-- === FILE: add_night_shift_config_areas.sql === --
-- ChronosWork â€” MigraciÃ³n: configuraciÃ³n de jornada nocturna por Ã¡rea -- Ejecutar en Supabase SQL Editor  ALTER TABLE areas   ADD COLUMN IF NOT EXISTS night_shift_enabled   BOOLEAN DEFAULT false,   ADD COLUMN IF NOT EXISTS night_shift_start      TEXT    DEFAULT '22:00',   ADD COLUMN IF NOT EXISTS night_shift_end        TEXT    DEFAULT '06:00',   ADD COLUMN IF NOT EXISTS night_shift_employee_ids UUID[] DEFAULT '{}';  COMMENT ON COLUMN areas.night_shift_enabled   IS 'Si true, hay una jornada nocturna dedicada (solo aplica en modo 24_7)'; COMMENT ON COLUMN areas.night_shift_start   IS 'Hora de inicio de la jornada nocturna, ej: 22:00'; COMMENT ON COLUMN areas.night_shift_end   IS 'Hora de fin de la jornada nocturna (puede cruzar medianoche), ej: 06:00'; COMMENT ON COLUMN areas.night_shift_employee_ids   IS 'IDs de empleados asignados exclusivamente a la jornada nocturna. Si estÃ¡ vacÃ­o, el sistema los elige automÃ¡ticamente.';

-- === FILE: add_defaults_areas.sql === --
-- ============================================================ -- ChronosWork â€” MigraciÃ³n: defaults de contrato en Ã¡reas -- Agrega tipo_contrato_default y dias_descanso_default a la -- tabla areas para que al asignar un Ã¡rea a un empleado se -- arrastren automÃ¡ticamente estos valores al formulario. -- -- Ejecutar en: Supabase SQL Editor -- ============================================================  ALTER TABLE areas   ADD COLUMN IF NOT EXISTS tipo_contrato_default VARCHAR(20)     DEFAULT 'POR_HORAS'     CHECK (tipo_contrato_default IN ('SALARIO_FIJO', 'POR_HORAS')),   ADD COLUMN IF NOT EXISTS dias_descanso_default INT     DEFAULT 1     CHECK (dias_descanso_default IN (1, 2));  COMMENT ON COLUMN areas.tipo_contrato_default IS   'Tipo de contrato por defecto para nuevos empleados de esta Ã¡rea (POR_HORAS | SALARIO_FIJO)'; COMMENT ON COLUMN areas.dias_descanso_default IS   'DÃ­as de descanso semanal por defecto para nuevos empleados de esta Ã¡rea (1 | 2)';  -- Opcional: actualizar Ã¡reas existentes con modo_operacion 24_7 -- a tipo_contrato_default = 'POR_HORAS' (ya estÃ¡ asÃ­ por defecto, pero -- puedes ajustar manualmente segÃºn tu configuraciÃ³n actual). -- UPDATE areas SET tipo_contrato_default = 'POR_HORAS', dias_descanso_default = 1 --   WHERE modo_operacion = '24_7';

-- === FILE: expand_employees_laboral.sql === --
-- ============================================================ -- ChronosWork â€” MigraciÃ³n 004: Ampliar `employees` con datos laborales CO -- Ejecutar en Supabase SQL Editor -- ============================================================ -- AmplÃ­a la tabla employees con todos los campos necesarios para -- liquidaciÃ³n de nÃ³mina y administraciÃ³n de personal colombiano: -- contrato, ARL, EPS, AFP, cesantÃ­as, salarios, datos personales, etc. -- ============================================================  -- â”€â”€ 1. Cambiar el CHECK de tipo_contrato para incluir todos los tipos â”€â”€â”€â”€â”€â”€ ALTER TABLE employees   DROP CONSTRAINT IF EXISTS employees_tipo_contrato_check;  ALTER TABLE employees   ALTER COLUMN tipo_contrato TYPE VARCHAR(20);  -- Si no existe CHECK, lo creamos DO $$ BEGIN   IF NOT EXISTS (     SELECT 1 FROM information_schema.table_constraints     WHERE table_name = 'employees' AND constraint_name = 'employees_tipo_contrato_check'   ) THEN     ALTER TABLE employees       ADD CONSTRAINT employees_tipo_contrato_check       CHECK (tipo_contrato IN (         'INDEFINIDO','TERMINO_FIJO','OBRA_LABOR','POR_HORAS','SALARIO_FIJO',         'PRESTACION_SERVICIOS','APRENDIZAJE','OCASIONAL','TEMPORAL'       ));   END IF; END $$;  -- â”€â”€ 2. Datos personales adicionales â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ ALTER TABLE employees   ADD COLUMN IF NOT EXISTS tipo_documento       VARCHAR(5) DEFAULT 'CC'     CHECK (tipo_documento IN ('CC','CE','TI','PA','RC','PPT','NIT')),   ADD COLUMN IF NOT EXISTS lugar_expedicion     VARCHAR(80),   ADD COLUMN IF NOT EXISTS fecha_nacimiento     DATE,   ADD COLUMN IF NOT EXISTS genero               VARCHAR(20)     CHECK (genero IN ('M','F','OTRO','PREFIERO_NO_DECIR')),   ADD COLUMN IF NOT EXISTS estado_civil         VARCHAR(20)     CHECK (estado_civil IN ('SOLTERO','CASADO','UNION_LIBRE','DIVORCIADO','VIUDO','SEPARADO')),   ADD COLUMN IF NOT EXISTS direccion            TEXT,   ADD COLUMN IF NOT EXISTS ciudad               VARCHAR(80),   ADD COLUMN IF NOT EXISTS departamento         VARCHAR(80),   ADD COLUMN IF NOT EXISTS telefono_contacto    VARCHAR(20),   ADD COLUMN IF NOT EXISTS email_personal       VARCHAR(150),   ADD COLUMN IF NOT EXISTS contacto_emergencia_nombre    VARCHAR(200),   ADD COLUMN IF NOT EXISTS contacto_emergencia_telefono  VARCHAR(20),   ADD COLUMN IF NOT EXISTS contacto_emergencia_parentesco VARCHAR(50),   ADD COLUMN IF NOT EXISTS numero_hijos         INT DEFAULT 0,   ADD COLUMN IF NOT EXISTS tiene_discapacidad   BOOLEAN DEFAULT false,   ADD COLUMN IF NOT EXISTS descripcion_discapacidad TEXT;  -- â”€â”€ 3. Datos contractuales completos â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ ALTER TABLE employees   ADD COLUMN IF NOT EXISTS fecha_ingreso        DATE,   ADD COLUMN IF NOT EXISTS fecha_fin_contrato   DATE,  -- para tÃ©rmino fijo/obra   ADD COLUMN IF NOT EXISTS periodo_prueba_hasta DATE,   ADD COLUMN IF NOT EXISTS cargo_codigo         VARCHAR(30),  -- p.ej. CIUO-08: "5221"   ADD COLUMN IF NOT EXISTS nivel_cargo          VARCHAR(30)     CHECK (nivel_cargo IN ('JUNIOR','SENIOR','COORDINADOR','SUPERVISOR','JEFE','GERENTE','DIRECTOR')),   ADD COLUMN IF NOT EXISTS reporta_a            UUID REFERENCES employees(id) ON DELETE SET NULL,   ADD COLUMN IF NOT EXISTS es_jefe              BOOLEAN DEFAULT false,   ADD COLUMN IF NOT EXISTS subordinados_ids     UUID[] DEFAULT '{}';  -- â”€â”€ 4. ConfiguraciÃ³n salarial extendida â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ ALTER TABLE employees   ADD COLUMN IF NOT EXISTS salario_mensual      DECIMAL(12,2),  -- para SALARIO_FIJO (sueldo pactado)   ADD COLUMN IF NOT EXISTS valor_hora           DECIMAL(12,2),  -- para POR_HORAS (ya existe como valor_hora, redundante OK)   ADD COLUMN IF NOT EXISTS auxiliar_areas_ids   UUID[] DEFAULT '{}',  -- Ã¡reas secundarias   ADD COLUMN IF NOT EXISTS bono_rodamiento      DECIMAL(12,2) DEFAULT 0,  -- p.ej. minero   ADD COLUMN IF NOT EXISTS bonificacion_fija    DECIMAL(12,2) DEFAULT 0,   ADD COLUMN IF NOT EXISTS recibe_auxilio_transporte BOOLEAN DEFAULT true,   ADD COLUMN IF NOT EXISTS aplica_pago_dominical       BOOLEAN DEFAULT true,   ADD COLUMN IF NOT EXISTS aplica_horas_extras         BOOLEAN DEFAULT true;  -- â”€â”€ 5. Seguridad social (Aportes a salud, pensiÃ³n, ARL) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ ALTER TABLE employees   ADD COLUMN IF NOT EXISTS eps_nombre           VARCHAR(100),  -- Nueva EPS, Sanitas, Sura, etc.   ADD COLUMN IF NOT EXISTS eps_codigo           VARCHAR(20),   ADD COLUMN IF NOT EXISTS afp_nombre           VARCHAR(100),  -- Porvenir, ProtecciÃ³n, Colfondos, Skandia   ADD COLUMN IF NOT EXISTS afp_codigo           VARCHAR(20),   ADD COLUMN IF NOT EXISTS afp_tipo             VARCHAR(20) DEFAULT 'RAZON'     CHECK (afp_tipo IN ('RAZON','PRIMAPROMEDIO')),  -- medio de cÃ¡lculo pensiÃ³n   ADD COLUMN IF NOT EXISTS arl_nombre           VARCHAR(100),  -- Sura, Positiva, BolÃ­var, Colmena   ADD COLUMN IF NOT EXISTS arl_codigo           VARCHAR(20),   ADD COLUMN IF NOT EXISTS nivel_riesgo_arl     INT DEFAULT 1     CHECK (nivel_riesgo_arl IN (1,2,3,4,5)),   ADD COLUMN IF NOT EXISTS caja_compensacion    VARCHAR(100),  -- Compensar, Comfama, Comfenalco   ADD COLUMN IF NOT EXISTS caja_codigo          VARCHAR(20),   ADD COLUMN IF NOT EXISTS fondo_cesantias      VARCHAR(100),  -- ProtecciÃ³n, Porvenir, BBVA, etc.   ADD COLUMN IF NOT EXISTS cesantias_afc        BOOLEAN DEFAULT false;  -- cuentas AFC  -- â”€â”€ 6. Datos bancarios â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ ALTER TABLE employees   ADD COLUMN IF NOT EXISTS banco_nombre         VARCHAR(80),   ADD COLUMN IF NOT EXISTS tipo_cuenta          VARCHAR(20)     CHECK (tipo_cuenta IN ('AHORROS','CORRIENTE')),   ADD COLUMN IF NOT EXISTS numero_cuenta        VARCHAR(30),   ADD COLUMN IF NOT EXISTS titular_cuenta       VARCHAR(200);  -- â”€â”€ 7. Datos acadÃ©micos / formativos â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ ALTER TABLE employees   ADD COLUMN IF NOT EXISTS nivel_educacion      VARCHAR(30)     CHECK (nivel_educacion IN (       'PRIMARIA','BACHILLERATO','TECNICO','TECNOLOGO','PREGRADO',       'ESPECIALIZACION','MAESTRIA','DOCTORADO','NINGUNO'     )),   ADD COLUMN IF NOT EXISTS titulo_obtenido      VARCHAR(150),   ADD COLUMN IF NOT EXISTS sena_aprendiz        BOOLEAN DEFAULT false,   ADD COLUMN IF NOT EXISTS etapa_productiva     BOOLEAN DEFAULT false,  -- solo para aprendices   ADD COLUMN IF NOT EXISTS fecha_etapa_lectiva_inicio DATE,   ADD COLUMN IF NOT EXISTS fecha_etapa_lectiva_fin    DATE;  -- â”€â”€ 8. Datos tributarios â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ ALTER TABLE employees   ADD COLUMN IF NOT EXISTS responsable_iva      BOOLEAN DEFAULT false,   ADD COLUMN IF NOT EXISTS declarante_renta     BOOLEAN DEFAULT false,   ADD COLUMN IF NOT EXISTS aplica_retencion_fuente BOOLEAN DEFAULT true,   ADD COLUMN IF NOT EXISTS numero_dependientes  INT DEFAULT 0,   ADD COLUMN IF NOT EXISTS persona_mayor_dependiente BOOLEAN DEFAULT false;  -- â”€â”€ 9. Permisos y certificaciones â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ ALTER TABLE employees   ADD COLUMN IF NOT EXISTS tiene_licencia_conduccion BOOLEAN DEFAULT false,   ADD COLUMN IF NOT EXISTS categoria_licencia        VARCHAR(5),  -- A1, B1, C1, etc.   ADD COLUMN IF NOT EXISTS vencimiento_licencia      DATE,   ADD COLUMN IF NOT EXISTS tiene_certificaciones     TEXT;  -- libre  -- â”€â”€ 10. ConfiguraciÃ³n de jornada y descanso â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ ALTER TABLE employees   ADD COLUMN IF NOT EXISTS horas_semanales_contrato   INT DEFAULT 48,  -- antes de Ley 2101 era 48, ahora 42   ADD COLUMN IF NOT EXISTS horas_mensuales_contrato   INT,   ADD COLUMN IF NOT EXISTS jornada_partida            BOOLEAN DEFAULT false,   ADD COLUMN IF NOT EXISTS turno_fijo                 BOOLEAN DEFAULT false,   ADD COLUMN IF NOT EXISTS turno_predeterminado_id    UUID REFERENCES shift_templates(id) ON DELETE SET NULL,   ADD COLUMN IF NOT EXISTS dias_descanso_fijos        INT[] DEFAULT '{}',  -- p.ej. {6,7} = descansa S-D   ADD COLUMN IF NOT EXISTS duracion_jornada_horas     DECIMAL(4,1) DEFAULT 8;  -- â”€â”€ 11. AuditorÃ­a â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ ALTER TABLE employees   ADD COLUMN IF NOT EXISTS updated_at  TIMESTAMPTZ DEFAULT NOW();  DROP TRIGGER IF EXISTS trg_employees_updated_at ON employees; CREATE TRIGGER trg_employees_updated_at   BEFORE UPDATE ON employees   FOR EACH ROW   EXECUTE FUNCTION set_updated_at();  -- â”€â”€ 12. Ãndices â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ CREATE INDEX IF NOT EXISTS idx_employees_eps    ON employees(tenant_id, eps_codigo); CREATE INDEX IF NOT EXISTS idx_employees_afp    ON employees(tenant_id, afp_codigo); CREATE INDEX IF NOT EXISTS idx_employees_ingreso ON employees(tenant_id, fecha_ingreso); CREATE INDEX IF NOT EXISTS idx_employees_contrato ON employees(tenant_id, tipo_contrato); CREATE INDEX IF NOT EXISTS idx_employees_jefe   ON employees(reporta_a);  -- â”€â”€ 13. Comentarios â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ COMMENT ON COLUMN employees.tipo_contrato IS   'INDEFINIDO: contrato a tÃ©rmino indefinido (CST art. 47).    TERMINO_FIJO: plazo definido (no puede fraccionarse en < 1 aÃ±o desde Ley 2466/2025).    OBRA_LABOR: hasta terminar la obra (CST art. 45).    POR_HORAS: hasta 30h/sem, min 4h consecutivas (CST art. 47, Ley 2101/21).    SALARIO_FIJO: mensual con turno predeterminado.    PRESTACION_SERVICIOS: autÃ³nomo, sin prestaciones (CÃ“DIGO CIVIL + C-201/24).    APRENDIZAJE: SENA. Etapa lectiva: 4h teÃ³ricas pagas. Productiva: 50% SMLV (Ley 1882/18).    OCASIONAL: hasta 30 dÃ­as, sin prestaciones (CST art. 6Â°).    TEMPORAL: a travÃ©s de EST, mÃ¡ximo 1 aÃ±o (Ley 50/90 art. 71).'; COMMENT ON COLUMN employees.afp_tipo IS   'RAZON: salario del Ãºltimo mes (mÃ¡s comÃºn).    PRIMAPROMEDIO: promedio de los Ãºltimos 10 aÃ±os (si ha cotizado <10, usa el promedio de los cotizados).'; COMMENT ON COLUMN employees.recibe_auxilio_transporte IS   'Aplica para empleados con sueldo â‰¤ 2 SMLV (Ley 2155/21). Monto 2025: $200.000.'; COMMENT ON COLUMN employees.horas_semanales_contrato IS   'Horas semanales contratadas. A partir de Ley 2101/2021, la jornada ordinaria es 42h/sem.';

-- === FILE: expand_areas_laboral.sql === --
-- ============================================================ -- ChronosWork â€” MigraciÃ³n 003: Ampliar `areas` con datos laborales CO -- Ejecutar en Supabase SQL Editor -- ============================================================ -- AÃ±ade campos para configurar el Ã¡rea de forma completa -- desde el dÃ­a 1, alineado al CST, Ley 2101/2021, Ley 2466/2025. -- Los campos son nullable o con default para que las Ã¡reas -- existentes no se rompan. -- ============================================================  -- â”€â”€ 1. Identidad del Ã¡rea â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ ALTER TABLE areas   ADD COLUMN IF NOT EXISTS codigo_area      VARCHAR(20),   -- ej: "CAJ-01"   ADD COLUMN IF NOT EXISTS sector           VARCHAR(30),   -- RETAIL, SALUD, etc.   ADD COLUMN IF NOT EXISTS sub_sector       VARCHAR(50),   -- opcional, libre   ADD COLUMN IF NOT EXISTS centro_costo     VARCHAR(30),   -- p.ej. para reportes contables   ADD COLUMN IF NOT EXISTS jornada_tipo     VARCHAR(20) DEFAULT 'DIURNA'     CHECK (jornada_tipo IN ('DIURNA','NOCTURNA','MIXTA','POR_TURNOS'));  -- â”€â”€ 2. ConfiguraciÃ³n legal / jornada â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ ALTER TABLE areas   ADD COLUMN IF NOT EXISTS duracion_jornada_horas   DECIMAL(4,1) DEFAULT 8,   ADD COLUMN IF NOT EXISTS horas_extras_max_dia      INT DEFAULT 2,   ADD COLUMN IF NOT EXISTS horas_extras_max_semana   INT DEFAULT 12,   ADD COLUMN IF NOT EXISTS descanso_min_entre_jornadas INT DEFAULT 9,  -- horas   ADD COLUMN IF NOT EXISTS dias_descanso             INT DEFAULT 1,    -- patrÃ³n: 1 o 2   ADD COLUMN IF NOT EXISTS patron_rotativo          VARCHAR(15),      -- 2x1, 3x2, 4x3, 5x2, 6x1, 7x7, 10x5, 14x14, PERSONALIZADO   ADD COLUMN IF NOT EXISTS jornada_partida          BOOLEAN DEFAULT false,   ADD COLUMN IF NOT EXISTS jornada_partida_inicio    TIME,             -- ej 07:00   ADD COLUMN IF NOT EXISTS jornada_partida_fin       TIME,             -- ej 12:00   ADD COLUMN IF NOT EXISTS jornada_partida_reinicio  TIME,             -- ej 13:00   ADD COLUMN IF NOT EXISTS jornada_partida_termino   TIME,             -- ej 17:00   ADD COLUMN IF NOT EXISTS break_minutos             INT DEFAULT 0,    -- almuerzo (ya no se paga, pero se usa para liquidaciÃ³n)   ADD COLUMN IF NOT EXISTS requiere_marca_asistencia BOOLEAN DEFAULT false; -- kiosko/QR  -- â”€â”€ 3. ConfiguraciÃ³n de turno nocturno (24/7) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ -- Las columnas ya existen de add_night_shift_config_areas.sql -- AquÃ­ solo las extendemos si faltan ALTER TABLE areas   ADD COLUMN IF NOT EXISTS night_shift_paga_hon          BOOLEAN DEFAULT true,   ADD COLUMN IF NOT EXISTS night_shift_porcentaje_umbral INT DEFAULT 50;  -- 50% del turno debe ser nocturno  -- â”€â”€ 4. ConfiguraciÃ³n salarial y contractual â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ ALTER TABLE areas   ADD COLUMN IF NOT EXISTS tipo_contrato_predominante VARCHAR(20) DEFAULT 'INDEFINIDO'     CHECK (tipo_contrato_predominante IN (       'INDEFINIDO','TERMINO_FIJO','OBRA_LABOR','POR_HORAS','SALARIO_FIJO',       'PRESTACION_SERVICIOS','APRENDIZAJE','OCASIONAL','TEMPORAL'     )),   ADD COLUMN IF NOT EXISTS paga_auxilio_transporte     BOOLEAN DEFAULT true,   ADD COLUMN IF NOT EXISTS nivel_riesgo_arl            INT DEFAULT 1     CHECK (nivel_riesgo_arl IN (1,2,3,4,5)),  -- I a V, clase de riesgo   ADD COLUMN IF NOT EXISTS tarifa_arl_por_mil          DECIMAL(8,4) DEFAULT 0.522,  -- % mensual sobre IBC para nivel I   ADD COLUMN IF NOT EXISTS aplica_pago_dominical       BOOLEAN DEFAULT true,   ADD COLUMN IF NOT EXISTS horario_especial            BOOLEAN DEFAULT false;  -- Ley 2466/2025  -- â”€â”€ 5. DotaciÃ³n y elementos â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ ALTER TABLE areas   ADD COLUMN IF NOT EXISTS requiere_dotacion             BOOLEAN DEFAULT false,   ADD COLUMN IF NOT EXISTS dotacion_periodicidad_meses   INT DEFAULT 4,  -- 4 meses (Art. 230 CST)   ADD COLUMN IF NOT EXISTS requiere_epp                 BOOLEAN DEFAULT false,  -- Elementos ProtecciÃ³n Personal   ADD COLUMN IF NOT EXISTS descripcion_epp              TEXT;  -- ej: "Casco, botas punta acero, gafas"  -- â”€â”€ 6. Centro de trabajo / ubicaciÃ³n â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ ALTER TABLE areas   ADD COLUMN IF NOT EXISTS sede_id          UUID,           -- para multi-sede   ADD COLUMN IF NOT EXISTS direccion        TEXT,   ADD COLUMN IF NOT EXISTS ciudad           VARCHAR(80) DEFAULT 'BogotÃ¡',   ADD COLUMN IF NOT EXISTS departamento     VARCHAR(80) DEFAULT 'Cundinamarca',   ADD COLUMN IF NOT EXISTS latitud          DECIMAL(10,7),   ADD COLUMN IF NOT EXISTS longitud         DECIMAL(10,7),   ADD COLUMN IF NOT EXISTS radio_geofence_m INT DEFAULT 150;  -- â”€â”€ 7. Prestaciones y beneficios del Ã¡rea â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ ALTER TABLE areas   ADD COLUMN IF NOT EXISTS incluye_prima_servicios       BOOLEAN DEFAULT true,   ADD COLUMN IF NOT EXISTS incluye_cesantias             BOOLEAN DEFAULT true,   ADD COLUMN IF NOT EXISTS incluye_intereses_cesantias   BOOLEAN DEFAULT true,   ADD COLUMN IF NOT EXISTS incluye_vacaciones            BOOLEAN DEFAULT true,   ADD COLUMN IF NOT EXISTS prima_legal_anual             BOOLEAN DEFAULT true,  -- 1 salario / aÃ±o   ADD COLUMN IF NOT EXISTS bono_extra_legal              BOOLEAN DEFAULT false, -- p.ej. Rodamiento minera   ADD COLUMN IF NOT EXISTS bono_monto_fijo_mensual       DECIMAL(12,2);  -- â”€â”€ 8. ConfiguraciÃ³n presupuestal â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ ALTER TABLE areas   ADD COLUMN IF NOT EXISTS presupuesto_mensual           DECIMAL(14,2),   ADD COLUMN IF NOT EXISTS alerta_sobrecosto_porcentaje  INT DEFAULT 110;  -- avisa si llega al 110% del presupuesto  -- â”€â”€ 9. Flags operativos â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ ALTER TABLE areas   ADD COLUMN IF NOT EXISTS permite_turno_partido         BOOLEAN DEFAULT true,   ADD COLUMN IF NOT EXISTS permite_rotacion_interna      BOOLEAN DEFAULT true,   ADD COLUMN IF NOT EXISTS tiene_turno_fijo              BOOLEAN DEFAULT false,   ADD COLUMN IF NOT EXISTS notas_operativas              TEXT;  -- â”€â”€ 10. AuditorÃ­a â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ ALTER TABLE areas   ADD COLUMN IF NOT EXISTS updated_at  TIMESTAMPTZ DEFAULT NOW(),   ADD COLUMN IF NOT EXISTS updated_by  UUID REFERENCES auth.users(id) ON DELETE SET NULL;  -- â”€â”€ 11. Ãndices para filtros frecuentes â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ CREATE INDEX IF NOT EXISTS idx_areas_sector        ON areas(tenant_id, sector); CREATE INDEX IF NOT EXISTS idx_areas_patron        ON areas(tenant_id, patron_rotativo); CREATE INDEX IF NOT EXISTS idx_areas_jornada_tipo  ON areas(tenant_id, jornada_tipo); CREATE INDEX IF NOT EXISTS idx_areas_sede          ON areas(sede_id);  -- â”€â”€ 12. FunciÃ³n para autogestionar updated_at â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ CREATE OR REPLACE FUNCTION set_updated_at() RETURNS TRIGGER AS $$ BEGIN   NEW.updated_at = NOW();   RETURN NEW; END; $$ LANGUAGE plpgsql;  DROP TRIGGER IF EXISTS trg_areas_updated_at ON areas; CREATE TRIGGER trg_areas_updated_at   BEFORE UPDATE ON areas   FOR EACH ROW   EXECUTE FUNCTION set_updated_at();  -- â”€â”€ 13. Comentarios para documentar el schema â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ COMMENT ON COLUMN areas.sector IS   'Sector econÃ³mico (RETAIL, SALUD, INDUSTRIA, etc.) â€” se usa para sugerir Ã¡reas, franjas y salarios tÃ­picos.'; COMMENT ON COLUMN areas.duracion_jornada_horas IS   'DuraciÃ³n de la jornada ordinaria por turno (ej: 8, 10, 12). No incluye hora de almuerzo.'; COMMENT ON COLUMN areas.patron_rotativo IS   'PatrÃ³n de trabajo/descanso. Ej: 5x2 (L-V), 6x1, 7x7, 14x14. PERSONALIZADO = definido por dias_trabajo.'; COMMENT ON COLUMN areas.jornada_partida IS   'true si la jornada se interrumpe para almuerzo (no se paga la interrupciÃ³n, jurisprudencia).'; COMMENT ON COLUMN areas.nivel_riesgo_arl IS   'Clase de riesgo ARL (Decreto 1295/94). I=0.522%, II=1.044%, III=2.436%, IV=4.350%, V=6.960%.'; COMMENT ON COLUMN areas.horario_especial IS   'true si el Ã¡rea tiene horario especial bajo Ley 2466/2025 (sectores crÃ­ticos).';

-- === FILE: expand_shift_templates.sql === --
-- ============================================================ -- ChronosWork â€” MigraciÃ³n 005: Ampliar `shift_templates` con tipos de turno -- Ejecutar en Supabase SQL Editor -- ============================================================ -- El campo shift_kind define el comportamiento del turno en el -- algoritmo de auto-asignaciÃ³n. Los valores permitidos son: --   STANDARD        : turno corrido simple --   PARTIDO         : con hora de almuerzo (split shift) --   ROTATIVO        : rotativo entre maÃ±ana/tarde/noche --   NOCTURNO        : predominantemente nocturno (HON automÃ¡tico) --   DISPONIBILIDAD  : guardia on-call --   CUSTOM          : definido por el usuario -- ============================================================  ALTER TABLE shift_templates   ADD COLUMN IF NOT EXISTS shift_kind          VARCHAR(20) DEFAULT 'STANDARD'     CHECK (shift_kind IN ('STANDARD','PARTIDO','ROTATIVO','NOCTURNO','DISPONIBILIDAD','CUSTOM')),   -- Para turnos partidos (dos bloques)   ADD COLUMN IF NOT EXISTS hora_inicio_2       TIME,   ADD COLUMN IF NOT EXISTS hora_fin_2          TIME,   ADD COLUMN IF NOT EXISTS split_break_minutos INT DEFAULT 60,  -- duraciÃ³n del intermedio   -- Para turnos rotativos   ADD COLUMN IF NOT EXISTS rotacion_patron     VARCHAR(15),     -- 2x1, 3x2, 4x3, 5x2, 6x1, 7x7, 10x5, 14x14   ADD COLUMN IF NOT EXISTS rotacion_posicion   INT,             -- 0 = primero en rotar (maÃ±ana), 1 = segundo (tarde), etc.   -- Disponibilidad / on-call   ADD COLUMN IF NOT EXISTS disponibilidad_recargo_porcentaje DECIMAL(5,2) DEFAULT 0,  -- % extra por estar on-call   -- Etiquetas / bÃºsqueda   ADD COLUMN IF NOT EXISTS descripcion         TEXT,   ADD COLUMN IF NOT EXISTS etiquetas           TEXT[] DEFAULT '{}',  -- p.ej. {'apertura','fin de semana'}   -- ConfiguraciÃ³n legal   ADD COLUMN IF NOT EXISTS paga_recargo_dominical   BOOLEAN DEFAULT true,   ADD COLUMN IF NOT EXISTS paga_recargo_nocturno    BOOLEAN DEFAULT false,   ADD COLUMN IF NOT EXISTS requiere_descanso_antes  BOOLEAN DEFAULT true,  -- respeta 9h descanso previo   -- AuditorÃ­a   ADD COLUMN IF NOT EXISTS updated_at          TIMESTAMPTZ DEFAULT NOW();  DROP TRIGGER IF EXISTS trg_shift_templates_updated_at ON shift_templates; CREATE TRIGGER trg_shift_templates_updated_at   BEFORE UPDATE ON shift_templates   FOR EACH ROW   EXECUTE FUNCTION set_updated_at();  -- â”€â”€ Ãndices para filtros por tipo de turno â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ CREATE INDEX IF NOT EXISTS idx_shift_templates_kind   ON shift_templates(tenant_id, shift_kind); CREATE INDEX IF NOT EXISTS idx_shift_templates_patron ON shift_templates(tenant_id, rotacion_patron);  -- â”€â”€ Comentarios â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ COMMENT ON COLUMN shift_templates.shift_kind IS   'STANDARD: turno corrido (ej 6-2, 8-5).    PARTIDO: con hora de almuerzo (ej 7-12 y 14-18).    ROTATIVO: el sistema rota el patrÃ³n entre varios turnos.    NOCTURNO: predominantemente nocturno (â‰¥50% del turno entre 19:00-06:00).    DISPONIBILIDAD: guardia on-call, se paga un recargo por disponibilidad.    CUSTOM: definido libremente por el usuario.'; COMMENT ON COLUMN shift_templates.rotacion_patron IS   'PatrÃ³n de rotaciÃ³n (2x1, 3x2, 4x3, 5x2, 6x1, 7x7, 10x5, 14x14). Solo aplica a shift_kind=ROTATIVO.'; COMMENT ON COLUMN shift_templates.paga_recargo_nocturno IS   'true si este turno genera recargo HON (Hora Ordinaria Nocturna) en liquidaciÃ³n.';

-- === FILE: fix_employees_sector.sql === --
-- ============================================================ -- ChronosWork â€” Fix: agregar columna `sector` a la tabla `employees` -- ============================================================ -- El modal de importaciÃ³n masiva (BulkImportModal.jsx) envÃ­a -- el campo `sector` del Excel al insertar empleados. Pero la -- tabla `employees` no tenÃ­a esa columna, lo que provocaba: --   "Could not find the 'sector' column of 'employees' in the schema cache" -- -- Esta migraciÃ³n agrega la columna con su CHECK constraint -- alineado a los sectores del catÃ¡logo SECTORES en laborCatalog.js. -- -- Es idempotente: se puede correr varias veces sin romper. -- ============================================================  -- 1) Agregar la columna (si no existe) ALTER TABLE public.employees   ADD COLUMN IF NOT EXISTS sector TEXT;  -- 2) Limpiar valores huÃ©rfanos (por si los hay) para que el CHECK no falle UPDATE public.employees SET sector = NULL WHERE sector IS NOT NULL   AND sector NOT IN (     'RETAIL', 'HOTELERIA', 'RESTAURANTE', 'SALUD', 'SEGURIDAD',     'INDUSTRIA', 'CONSTRUCCION', 'LOGISTICA', 'OFICINA', 'EDUCACION',     'AGRO', 'TECNOLOGIA', 'CALL_CENTER', 'OTRO'   );  -- 3) Eliminar CHECK constraint antiguo si existe ALTER TABLE public.employees   DROP CONSTRAINT IF EXISTS employees_sector_check;  -- 4) Crear CHECK constraint con los valores del catÃ¡logo SECTORES ALTER TABLE public.employees   ADD CONSTRAINT employees_sector_check   CHECK (     sector IS NULL OR sector IN (       'RETAIL', 'HOTELERIA', 'RESTAURANTE', 'SALUD', 'SEGURIDAD',       'INDUSTRIA', 'CONSTRUCCION', 'LOGISTICA', 'OFICINA', 'EDUCACION',       'AGRO', 'TECNOLOGIA', 'CALL_CENTER', 'OTRO'     )   );  -- 5) Ãndice para reportes / filtros rÃ¡pidos por sector CREATE INDEX IF NOT EXISTS idx_employees_sector   ON public.employees(tenant_id, sector)   WHERE sector IS NOT NULL;  -- 6) Comentario descriptivo COMMENT ON COLUMN public.employees.sector IS   'Sector econÃ³mico del empleado (catÃ¡logo SECTORES de laborCatalog.js). Independiente del sector del Ã¡rea donde trabaja.';  -- 7) VerificaciÃ³n DO $$ DECLARE   v_count INT; BEGIN   SELECT COUNT(*) INTO v_count   FROM information_schema.columns   WHERE table_schema = 'public'     AND table_name = 'employees'     AND column_name = 'sector';   IF v_count = 1 THEN     RAISE NOTICE 'âœ… Columna employees.sector creada correctamente.';   ELSE     RAISE EXCEPTION 'âŒ La columna employees.sector no se creÃ³. Revisa los logs.';   END IF; END $$;

-- === FILE: expand_employees_jornada_v4.sql === --
-- ============================================================ -- ChronosWork â€” MigraciÃ³n 005: ConfiguraciÃ³n de jornada por empleado -- Ejecutar en Supabase SQL Editor -- ============================================================ -- Permite que el algoritmo de auto-asignaciÃ³n distinga entre -- empleados que SOLO quieren turno de dÃ­a, SOLO nocturno, o mixto. -- Caso de uso: call center 24/7 donde la empresa escoge 2-3 -- empleados especÃ­ficos para cubrir la noche (22:00-06:00) y al -- resto los programa Ãºnicamente entre 04:00 y 22:00. -- ============================================================  -- â”€â”€ 1. Jornada preferida del empleado â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ ALTER TABLE employees   ADD COLUMN IF NOT EXISTS jornada_preferida VARCHAR(20) DEFAULT 'CUALQUIERA'     CHECK (jornada_preferida IN ('DIURNA','NOCTURNA','MIXTA','CUALQUIERA')),   ADD COLUMN IF NOT EXISTS solo_diurno        BOOLEAN DEFAULT false,   ADD COLUMN IF NOT EXISTS solo_nocturno      BOOLEAN DEFAULT false,   ADD COLUMN IF NOT EXISTS permite_partido    BOOLEAN DEFAULT false;  COMMENT ON COLUMN employees.jornada_preferida IS   'Preferencia del empleado. DIURNA: solo turnos entre 04:00 y 22:00.    NOCTURNA: solo turnos que toquen horario nocturno (>=19:00 o <06:00).    MIXTA: puede cubrir ambos segÃºn necesidad.    CUALQUIERA: el sistema decide segÃºn dÃ©ficit. Default del mercado CO.';  COMMENT ON COLUMN employees.solo_diurno IS   'Atajo para jornada_preferida=DIURNA. Si true, el algoritmo NUNCA le asigna noche.';  COMMENT ON COLUMN employees.solo_nocturno IS   'Atajo para jornada_preferida=NOCTURNA. Ãštil para empleados designados    por la empresa a cubrir la franja 22:00-06:00 en operaciÃ³n 24/7.';  COMMENT ON COLUMN employees.permite_partido IS   'Si true, se le puede asignar turnos partidos (maÃ±ana + tarde con break largo).';  -- â”€â”€ 2. LÃ­mites individuales adicionales â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ ALTER TABLE employees   ADD COLUMN IF NOT EXISTS horas_max_diarias          DECIMAL(4,1),   ADD COLUMN IF NOT EXISTS horas_nocturnas_max_semana INT,   ADD COLUMN IF NOT EXISTS horas_max_semana           INT,   ADD COLUMN IF NOT EXISTS duracion_jornada_horas     DECIMAL(4,1) DEFAULT 8;  -- duracion_jornada_horas ya existe en expand_employees_laboral.sql, redundancia OK COMMENT ON COLUMN employees.horas_max_diarias IS   'Override del mÃ¡ximo diario. NULL = usar el del Ã¡rea (default 10h).';  COMMENT ON COLUMN employees.horas_nocturnas_max_semana IS   'Tope individual de horas nocturnas semanales. NULL = sin tope (el legal).';  -- â”€â”€ 3. Backfill defensivo para empleados existentes â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ -- Si tienen turno_predeterminado_id y es NOCTURNO, marcarlos solo_nocturno UPDATE employees SET jornada_preferida = 'CUALQUIERA' WHERE jornada_preferida IS NULL;  -- â”€â”€ 4. Helper view: clasificaciÃ³n efectiva del empleado â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ CREATE OR REPLACE VIEW v_employee_jornada AS SELECT   e.id,   e.tenant_id,   e.nombre,   e.tipo_contrato,   e.turno_predeterminado_id,   e.horas_semanales_contrato,   e.dias_descanso_fijos,   e.solo_diurno,   e.solo_nocturno,   e.jornada_preferida,   e.permite_partido,   -- ClasificaciÃ³n efectiva   CASE     WHEN e.solo_nocturno THEN 'NIGHT_ONLY'     WHEN e.solo_diurno   THEN 'DAY_ONLY'     WHEN e.jornada_preferida = 'NOCTURNA' THEN 'NIGHT_ONLY'     WHEN e.jornada_preferida = 'DIURNA'   THEN 'DAY_ONLY'     WHEN e.jornada_preferida = 'MIXTA'    THEN 'MIXED'     ELSE 'ANY'   END AS jornada_efectiva FROM employees e WHERE e.activo = true;  COMMENT ON VIEW v_employee_jornada IS   'Vista que consolida la jornada efectiva de cada empleado para el algoritmo.    NIGHT_ONLY: solo se le asignan turnos nocturnos.    DAY_ONLY: nunca se le asigna un turno que toque horario nocturno.    MIXED: puede cubrir ambos segÃºn dÃ©ficit.    ANY: el sistema decide (jornada_preferida=CUALQUIERA).';  -- â”€â”€ 5. Ãndice para acelerar filtros del algoritmo â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ CREATE INDEX IF NOT EXISTS idx_employees_jornada_efectiva   ON employees(tenant_id, activo)   WHERE activo = true;

-- === FILE: expand_areas_estrategia_v4.sql === --
-- ============================================================ -- ChronosWork â€” MigraciÃ³n 006: Estrategia de asignaciÃ³n por Ã¡rea -- Ejecutar en Supabase SQL Editor -- ============================================================ -- AÃ±ade parÃ¡metros al Ã¡rea que controlan cÃ³mo el algoritmo -- prioriza: cobertura vs balanceo, granularidad de slots, -- mÃ­nimos nocturnos, etc. Pensado para call centers 24/7 -- pero aplica a cualquier operaciÃ³n con demanda variable. -- ============================================================  -- â”€â”€ 1. Modo de operaciÃ³n extendido â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ -- OFICINA: lunes a viernes jornada diurna (8h). -- 24_7: cobertura continua, todos los dÃ­as, todas las horas. -- 24_7_NIGHT_SPLIT: 24/7 con jornada nocturna dedicada (CASO CALL CENTER). ALTER TABLE areas   DROP CONSTRAINT IF EXISTS areas_modo_operacion_check; ALTER TABLE areas   ALTER COLUMN modo_operacion TYPE VARCHAR(30); ALTER TABLE areas   ADD CONSTRAINT areas_modo_operacion_check   CHECK (modo_operacion IN ('OFICINA','24_7','24_7_NIGHT_SPLIT'));  -- â”€â”€ 2. Estrategia de asignaciÃ³n â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ -- COVERAGE_FIRST: el algoritmo prioriza llenar la demanda configurada. --                 Recomendado para call center, salud, seguridad, 24/7. -- BALANCED: el algoritmo prioriza balancear horas entre empleados. --           Recomendado para oficinas, administrativos. -- EMPLOYEE_PREF: el algoritmo prioriza respetar la jornada_preferida --                del empleado, incluso a costa de dÃ©ficit de cobertura. ALTER TABLE areas   ADD COLUMN IF NOT EXISTS estrategia_asignacion VARCHAR(20) DEFAULT 'COVERAGE_FIRST'     CHECK (estrategia_asignacion IN ('COVERAGE_FIRST','BALANCED','EMPLOYEE_PREF'));  -- â”€â”€ 3. Config nocturna detallada (extiende lo que ya hay) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ ALTER TABLE areas   ADD COLUMN IF NOT EXISTS min_empleados_noche              INT DEFAULT 1,   ADD COLUMN IF NOT EXISTS permite_dia_cubrir_noche         BOOLEAN DEFAULT false,   ADD COLUMN IF NOT EXISTS noche_solo_empleados_dedicados   BOOLEAN DEFAULT true;  COMMENT ON COLUMN areas.min_empleados_noche IS   'MÃ­nimo de empleados simultÃ¡neos durante la franja nocturna (22:00-06:00).    Por defecto 1. En call center con bajo volumen nocturno puede ser 1.';  COMMENT ON COLUMN areas.permite_dia_cubrir_noche IS   'Si true, empleados con jornada_preferida=DIURNA pueden cubrir   å¶å°” un turno nocturno cuando no haya nadie disponible.';  COMMENT ON COLUMN areas.noche_solo_empleados_dedicados IS   'Si true, SOLO empleados con solo_nocturno=true o jornada_preferida    en {NOCTURNA, MIXTA} pueden ser asignados a la franja nocturna.    Default true (recomendado para proteger al personal diurno).';  -- â”€â”€ 4. Granularidad temporal del algoritmo â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ -- El algoritmo divide el dÃ­a en slots. Por defecto 4 slots/hora (15 min) -- que es lo que usa para evaluar la demanda continua. -- Para Ã¡reas mÃ¡s simples, se puede bajar a 1 slot/hora (60 min) y -- acelerar el cÃ¡lculo 4x. ALTER TABLE areas   ADD COLUMN IF NOT EXISTS slots_por_hora INT DEFAULT 4     CHECK (slots_por_hora IN (1,2,4));  -- â”€â”€ 5. ConfiguraciÃ³n de duraciÃ³n mÃ­nima/mÃ¡xima del turno â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ -- (extiende lo que ya estÃ¡ en la tabla, pero ahora es por Ã¡rea --  y se puede dejar NULL para que el sistema use defaults legales) ALTER TABLE areas   ADD COLUMN IF NOT EXISTS min_horas_turno_override  DECIMAL(4,1),   ADD COLUMN IF NOT EXISTS max_horas_turno_override  DECIMAL(4,1),   ADD COLUMN IF NOT EXISTS permitir_horas_extras     BOOLEAN DEFAULT false,   ADD COLUMN IF NOT EXISTS permitir_turno_partido    BOOLEAN DEFAULT false;  -- â”€â”€ 6. PolÃ­tica de balanceo semanal â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ ALTER TABLE areas   ADD COLUMN IF NOT EXISTS balancear_carga            BOOLEAN DEFAULT true,   ADD COLUMN IF NOT EXISTS rotar_slots_entre_asesores BOOLEAN DEFAULT false;  COMMENT ON COLUMN areas.balancear_carga IS   'Si true, al final de la generaciÃ³n el algoritmo intenta mover turnos    para que la diferencia entre el empleado con mÃ¡s horas y el de menos    no supere MAX_DIFERENCIA_HORAS. Default true (mercado CO).';  COMMENT ON COLUMN areas.rotar_slots_entre_asesores IS   'Si true, dentro de un mismo dÃ­a, distintos empleados cubren slots    adyacentes. Ãštil cuando quieres que varios asesores compartan la    misma franja (ej: 2 personas en 14:00-18:00).';  -- â”€â”€ 7. Tolerancia de inicio de turno (snap a grid) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ -- Define cada cuÃ¡ntos minutos los turnos se "ajustan" a la grilla. -- 15 = cada 15 min (4 slots/h), 30 = cada 30 min (2 slots/h), 60 = cada hora. -- Por defecto 15, alineado con la grilla del algoritmo. ALTER TABLE areas   ADD COLUMN IF NOT EXISTS snap_turnos_minutos INT DEFAULT 15     CHECK (snap_turnos_minutos IN (5,10,15,30,60));  -- â”€â”€ 8. Helper view: resumen de config del Ã¡rea â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ CREATE OR REPLACE VIEW v_area_strategy AS SELECT   a.id,   a.tenant_id,   a.nombre,   a.modo_operacion,   a.estrategia_asignacion,   a.jornada_tipo,   a.patron_rotativo,   a.night_shift_enabled,   a.night_shift_start,   a.night_shift_end,   a.min_empleados_noche,   a.noche_solo_empleados_dedicados,   a.permite_dia_cubrir_noche,   a.slots_por_hora,   a.snap_turnos_minutos,   a.balancear_carga,   a.rotar_slots_entre_asesores,   a.permitir_horas_extras,   a.permitir_turno_partido,   a.min_horas_turno_override,   a.max_horas_turno_override FROM areas a;  COMMENT ON VIEW v_area_strategy IS   'Vista consolidada con la estrategia completa del Ã¡rea para el algoritmo v4.0.';  -- â”€â”€ 9. Backfill: si la operaciÃ³n es 24/7 y el Ã¡rea no tiene min_noche, set 1 UPDATE areas SET min_empleados_noche = COALESCE(min_empleados_noche, 1) WHERE modo_operacion IN ('24_7','24_7_NIGHT_SPLIT');  UPDATE areas SET estrategia_asignacion = COALESCE(estrategia_asignacion, 'COVERAGE_FIRST') WHERE modo_operacion = '24_7' OR modo_operacion = '24_7_NIGHT_SPLIT';  UPDATE areas SET estrategia_asignacion = COALESCE(estrategia_asignacion, 'BALANCED') WHERE modo_operacion = 'OFICINA';

-- === FILE: fix_shifts_shift_kind.sql === --
-- ============================================================ -- ChronosWork â€” Fix: columnas faltantes en `shifts` -- Para soportar: shift_kind, bloque, disponibilidad, -- recargo_porcentaje, observaciones -- (las usa el algoritmo v3 de auto-asignaciÃ³n de turnos) -- ============================================================ -- Idempotente: se puede correr varias veces sin romper nada. -- Ejecutar en: Supabase SQL Editor -- ============================================================  -- â”€â”€ 1. AÃ±adir columnas a la tabla shifts â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ ALTER TABLE shifts   ADD COLUMN IF NOT EXISTS shift_kind           VARCHAR(20) DEFAULT 'STANDARD',   ADD COLUMN IF NOT EXISTS bloque               INT DEFAULT 1,   ADD COLUMN IF NOT EXISTS disponibilidad       BOOLEAN DEFAULT false,   ADD COLUMN IF NOT EXISTS recargo_porcentaje   DECIMAL(6,2) DEFAULT 0,   ADD COLUMN IF NOT EXISTS observaciones        TEXT;  -- â”€â”€ 2. CHECK constraint para shift_kind â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ DO $$ BEGIN   IF NOT EXISTS (     SELECT 1 FROM information_schema.table_constraints     WHERE table_name = 'shifts' AND constraint_name = 'shifts_shift_kind_check'   ) THEN     ALTER TABLE shifts       ADD CONSTRAINT shifts_shift_kind_check       CHECK (shift_kind IN ('STANDARD','PARTIDO','ROTATIVO','NOCTURNO','DISPONIBILIDAD','CUSTOM'));   END IF; END $$;  -- â”€â”€ 3. Backfill de filas existentes (defensivo) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ -- Si ya tienes turnos con shift_type = 'morning/afternoon/night', -- los mapeamos a su shift_kind correspondiente para mantener -- consistencia con los datos viejos. UPDATE shifts SET shift_kind = CASE   WHEN shift_type = 'night'  THEN 'NOCTURNO'   WHEN shift_type = 'custom' THEN 'STANDARD'   ELSE 'STANDARD' END WHERE shift_kind IS NULL OR shift_kind = '';  -- â”€â”€ 4. Ãndices para los filtros de liquidaciÃ³n de prenÃ³mina â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ CREATE INDEX IF NOT EXISTS idx_shifts_shift_kind        ON shifts(tenant_id, shift_kind); CREATE INDEX IF NOT EXISTS idx_shifts_disponibilidad    ON shifts(tenant_id, disponibilidad); CREATE INDEX IF NOT EXISTS idx_shifts_bloque            ON shifts(template_id, bloque);  -- â”€â”€ 5. Comentarios documentando las nuevas columnas â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ COMMENT ON COLUMN shifts.shift_kind IS   'STANDARD: turno corrido simple.    PARTIDO: con hora de almuerzo (2 bloques).    ROTATIVO: sistema rota entre varios turnos.    NOCTURNO: predominantemente nocturno (HON automÃ¡tico).    DISPONIBILIDAD: guardia on-call.    CUSTOM: definido por el usuario.'; COMMENT ON COLUMN shifts.bloque IS   'NÃºmero de bloque cuando el turno es PARTIDO (1 = maÃ±ana, 2 = tarde).'; COMMENT ON COLUMN shifts.disponibilidad IS   'true si el turno es de disponibilidad/guardia (paga recargo sin laborar).'; COMMENT ON COLUMN shifts.recargo_porcentaje IS   'Recargo % extra para turnos de disponibilidad, definido en la plantilla.'; COMMENT ON COLUMN shifts.observaciones IS   'Notas libres: ej. "Reprogramado por ausencia", "Cambio autorizado por jefe X", etc.';  -- â”€â”€ 6. VerificaciÃ³n final â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ DO $$ DECLARE   v_count INT; BEGIN   SELECT COUNT(*) INTO v_count   FROM information_schema.columns   WHERE table_name = 'shifts'     AND column_name IN ('shift_kind','bloque','disponibilidad','recargo_porcentaje','observaciones');    IF v_count = 5 THEN     RAISE NOTICE 'âœ… MigraciÃ³n exitosa: las 5 columnas nuevas estÃ¡n en shifts.';   ELSE     RAISE EXCEPTION 'âŒ Solo se encontraron % columnas de las 5 esperadas.', v_count;   END IF; END $$;

-- === FILE: areas_schema.sql === --
-- ============================================================ -- ChronosWork â€” Schema completo: Ãreas, Franjas Horarias y Turnos -- Ejecutar en: Supabase SQL Editor -- https://supabase.com/dashboard/project/nazvmxcbrmqzsfxlowkx/sql/new -- -- ORDEN CORRECTO (dependencias primero): --   1. areas --   2. area_employees --   3. shift_templates --   4. ALTER shifts ADD template_id  â† al final, cuando shift_templates ya existe -- ============================================================  -- â”€â”€ PASO 1: Tabla areas â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ CREATE TABLE IF NOT EXISTS areas (   id           UUID PRIMARY KEY DEFAULT uuid_generate_v4(),   tenant_id    UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,   nombre       VARCHAR(100) NOT NULL,   descripcion  TEXT,   color        VARCHAR(7) DEFAULT '#6366f1',   dias_trabajo INT[] DEFAULT '{1,2,3,4,5}',  -- 1=Lun â€¦ 7=Dom   valor_hora_default      NUMERIC(10, 2),   cobertura_minima_diaria INT DEFAULT 1,   cobertura_maxima_diaria INT DEFAULT 10,   cobertura_por_turno     JSONB DEFAULT '{}'::jsonb,   modo_operacion          VARCHAR(30) DEFAULT 'OFICINA' CHECK (modo_operacion IN ('OFICINA', '24_7', '24_7_NIGHT_SPLIT')),   activo       BOOLEAN DEFAULT true,   created_at   TIMESTAMPTZ DEFAULT NOW() );  CREATE INDEX IF NOT EXISTS idx_areas_tenant ON areas(tenant_id);  -- â”€â”€ PASO 2: Tabla area_employees â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ CREATE TABLE IF NOT EXISTS area_employees (   id          UUID PRIMARY KEY DEFAULT uuid_generate_v4(),   area_id     UUID NOT NULL REFERENCES areas(id) ON DELETE CASCADE,   employee_id UUID NOT NULL UNIQUE REFERENCES employees(id) ON DELETE CASCADE,   tenant_id   UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,   created_at  TIMESTAMPTZ DEFAULT NOW() );  CREATE INDEX IF NOT EXISTS idx_area_employees_area     ON area_employees(area_id); CREATE INDEX IF NOT EXISTS idx_area_employees_employee ON area_employees(employee_id);  -- â”€â”€ PASO 3: Tabla shift_templates â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ CREATE TABLE IF NOT EXISTS shift_templates (   id               UUID PRIMARY KEY DEFAULT uuid_generate_v4(),   tenant_id        UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,   area_id          UUID REFERENCES areas(id) ON DELETE CASCADE,  -- NULL = global   nombre           VARCHAR(80) NOT NULL,   hora_inicio      TIME NOT NULL,   hora_fin         TIME NOT NULL,   cruza_medianoche BOOLEAN DEFAULT false,   color            VARCHAR(7) DEFAULT '#3b82f6',   activo           BOOLEAN DEFAULT true,   created_at       TIMESTAMPTZ DEFAULT NOW() );  CREATE INDEX IF NOT EXISTS idx_shift_templates_tenant ON shift_templates(tenant_id); CREATE INDEX IF NOT EXISTS idx_shift_templates_area   ON shift_templates(area_id);  -- â”€â”€ PASO 4: Agregar template_id a shifts (ahora shift_templates ya existe) â”€â”€â”€ ALTER TABLE shifts   ADD COLUMN IF NOT EXISTS template_id UUID REFERENCES shift_templates(id) ON DELETE SET NULL;  CREATE INDEX IF NOT EXISTS idx_shifts_template ON shifts(template_id);  -- â”€â”€ PASO 5: RLS para las tres tablas nuevas â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€  -- areas ALTER TABLE areas ENABLE ROW LEVEL SECURITY;  DO $$ BEGIN   IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename='areas' AND policyname='areas_select') THEN     CREATE POLICY "areas_select" ON areas FOR SELECT USING (tenant_id = auth_tenant_id() OR is_platform_admin());   END IF;   IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename='areas' AND policyname='areas_insert') THEN     CREATE POLICY "areas_insert" ON areas FOR INSERT WITH CHECK (tenant_id = auth_tenant_id());   END IF;   IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename='areas' AND policyname='areas_update') THEN     CREATE POLICY "areas_update" ON areas FOR UPDATE USING (tenant_id = auth_tenant_id());   END IF;   IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename='areas' AND policyname='areas_delete') THEN     CREATE POLICY "areas_delete" ON areas FOR DELETE USING (tenant_id = auth_tenant_id());   END IF; END $$;  -- area_employees ALTER TABLE area_employees ENABLE ROW LEVEL SECURITY;  DO $$ BEGIN   IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename='area_employees' AND policyname='area_employees_select') THEN     CREATE POLICY "area_employees_select" ON area_employees FOR SELECT USING (tenant_id = auth_tenant_id() OR is_platform_admin());   END IF;   IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename='area_employees' AND policyname='area_employees_insert') THEN     CREATE POLICY "area_employees_insert" ON area_employees FOR INSERT WITH CHECK (tenant_id = auth_tenant_id());   END IF;   IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename='area_employees' AND policyname='area_employees_delete') THEN     CREATE POLICY "area_employees_delete" ON area_employees FOR DELETE USING (tenant_id = auth_tenant_id());   END IF; END $$;  -- shift_templates ALTER TABLE shift_templates ENABLE ROW LEVEL SECURITY;  DO $$ BEGIN   IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename='shift_templates' AND policyname='shift_templates_select') THEN     CREATE POLICY "shift_templates_select" ON shift_templates FOR SELECT USING (tenant_id = auth_tenant_id() OR is_platform_admin());   END IF;   IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename='shift_templates' AND policyname='shift_templates_insert') THEN     CREATE POLICY "shift_templates_insert" ON shift_templates FOR INSERT WITH CHECK (tenant_id = auth_tenant_id());   END IF;   IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename='shift_templates' AND policyname='shift_templates_update') THEN     CREATE POLICY "shift_templates_update" ON shift_templates FOR UPDATE USING (tenant_id = auth_tenant_id());   END IF;   IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename='shift_templates' AND policyname='shift_templates_delete') THEN     CREATE POLICY "shift_templates_delete" ON shift_templates FOR DELETE USING (tenant_id = auth_tenant_id());   END IF; END $$;

-- === FILE: add_modo_operacion_areas.sql === --
-- ============================================================ -- ChronosWork â€” MigraciÃ³n: modo_operacion en areas -- Ejecutar en Supabase SQL Editor -- ============================================================  -- Agrega el tipo de operaciÃ³n al Ã¡rea ALTER TABLE areas   ADD COLUMN IF NOT EXISTS modo_operacion VARCHAR(30) DEFAULT 'OFICINA'   CHECK (modo_operacion IN ('OFICINA', '24_7', '24_7_NIGHT_SPLIT'));  -- Comentario explicativo COMMENT ON COLUMN areas.modo_operacion IS   'OFICINA = jornada normal semana laboral (8-6, 6-2, 2-10 etc), 42h/sem.    24_7   = operaciÃ³n continua 7x24, turnos rotativos, todos los dÃ­as incluyendo domingos y festivos.';

-- === FILE: fix_all_check_constraints.sql === --
-- ============================================================ -- ChronosWork â€” MigraciÃ³n correctiva: TODOS los CHECK constraints -- Ejecutar en Supabase SQL Editor -- ============================================================ -- Este script: -- 1) Elimina y recrea TODOS los CHECK constraints con valores actualizados -- 2) Normaliza datos existentes que puedan tener valores viejos -- 3) Valida que las modificaciones funcionen -- ============================================================  -- â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ -- ðŸ› ï¸ HELPER: funciÃ³n para recrear CHECK de forma segura -- â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ CREATE OR REPLACE FUNCTION recreate_check_constraint(   p_table TEXT,   p_constraint_name TEXT,   p_check_sql TEXT ) RETURNS TEXT AS $$ DECLARE   v_exists BOOLEAN; BEGIN   -- Verificar si existe   SELECT EXISTS (     SELECT 1 FROM information_schema.table_constraints     WHERE table_name = p_table       AND constraint_name = p_constraint_name       AND constraint_type = 'CHECK'   ) INTO v_exists;    IF v_exists THEN     EXECUTE format('ALTER TABLE %I DROP CONSTRAINT %I', p_table, p_constraint_name);   END IF;    EXECUTE format('ALTER TABLE %I ADD CONSTRAINT %I %s', p_table, p_constraint_name, p_check_sql);    RETURN format('âœ… %I.%I recreado: %s', p_table, p_constraint_name, p_check_sql); END; $$ LANGUAGE plpgsql;  -- â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ -- ðŸ”§ 1. AREAS: tipo_contrato_default (tenÃ­a solo 2 valores) -- â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ -- Primero normalizar datos existentes UPDATE areas SET tipo_contrato_default = 'INDEFINIDO'   WHERE tipo_contrato_default IS NOT NULL     AND tipo_contrato_default NOT IN (       'INDEFINIDO','TERMINO_FIJO','OBRA_LABOR','POR_HORAS','SALARIO_FIJO',       'PRESTACION_SERVICIOS','APRENDIZAJE','OCASIONAL','TEMPORAL'     );  -- Eliminar todos los CHECK constraints que pueda tener DO $$ DECLARE r RECORD; BEGIN   FOR r IN (     SELECT conname FROM pg_constraint     WHERE conrelid = 'areas'::regclass       AND contype = 'c'       AND pg_get_constraintdef(oid) ILIKE '%tipo_contrato_default%'   ) LOOP     EXECUTE format('ALTER TABLE areas DROP CONSTRAINT IF EXISTS %I', r.conname);   END LOOP; END $$;  ALTER TABLE areas   ADD CONSTRAINT areas_tipo_contrato_default_check   CHECK (tipo_contrato_default IS NULL OR tipo_contrato_default IN (     'INDEFINIDO','TERMINO_FIJO','OBRA_LABOR','POR_HORAS','SALARIO_FIJO',     'PRESTACION_SERVICIOS','APRENDIZAJE','OCASIONAL','TEMPORAL'   ));  -- â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ -- ðŸ”§ 2. AREAS: tipo_contrato_predominante -- â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ DO $$ DECLARE r RECORD; BEGIN   FOR r IN (     SELECT conname FROM pg_constraint     WHERE conrelid = 'areas'::regclass       AND contype = 'c'       AND pg_get_constraintdef(oid) ILIKE '%tipo_contrato_predominante%'   ) LOOP     EXECUTE format('ALTER TABLE areas DROP CONSTRAINT IF EXISTS %I', r.conname);   END LOOP; END $$;  UPDATE areas SET tipo_contrato_predominante = 'INDEFINIDO'   WHERE tipo_contrato_predominante IS NOT NULL     AND tipo_contrato_predominante NOT IN (       'INDEFINIDO','TERMINO_FIJO','OBRA_LABOR','POR_HORAS','SALARIO_FIJO',       'PRESTACION_SERVICIOS','APRENDIZAJE','OCASIONAL','TEMPORAL'     );  ALTER TABLE areas   ADD CONSTRAINT areas_tipo_contrato_predominante_check   CHECK (tipo_contrato_predominante IS NULL OR tipo_contrato_predominante IN (     'INDEFINIDO','TERMINO_FIJO','OBRA_LABOR','POR_HORAS','SALARIO_FIJO',     'PRESTACION_SERVICIOS','APRENDIZAJE','OCASIONAL','TEMPORAL'   ));  -- â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ -- ðŸ”§ 3. AREAS: modo_operacion (incluye 24_7_NIGHT_SPLIT) -- â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ DO $$ DECLARE r RECORD; BEGIN   FOR r IN (     SELECT conname FROM pg_constraint     WHERE conrelid = 'areas'::regclass       AND contype = 'c'       AND pg_get_constraintdef(oid) ILIKE '%modo_operacion%'   ) LOOP     EXECUTE format('ALTER TABLE areas DROP CONSTRAINT IF EXISTS %I', r.conname);   END LOOP; END $$;  ALTER TABLE areas   ADD CONSTRAINT areas_modo_operacion_check   CHECK (modo_operacion IS NULL OR modo_operacion IN ('OFICINA', '24_7', '24_7_NIGHT_SPLIT'));  -- â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ -- ðŸ”§ 4. AREAS: jornada_tipo -- â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ DO $$ DECLARE r RECORD; BEGIN   FOR r IN (     SELECT conname FROM pg_constraint     WHERE conrelid = 'areas'::regclass       AND contype = 'c'       AND pg_get_constraintdef(oid) ILIKE '%jornada_tipo%'   ) LOOP     EXECUTE format('ALTER TABLE areas DROP CONSTRAINT IF EXISTS %I', r.conname);   END LOOP; END $$;  UPDATE areas SET jornada_tipo = 'DIURNA'   WHERE jornada_tipo IS NOT NULL     AND jornada_tipo NOT IN ('DIURNA','NOCTURNA','MIXTA','POR_TURNOS');  ALTER TABLE areas   ADD CONSTRAINT areas_jornada_tipo_check   CHECK (jornada_tipo IS NULL OR jornada_tipo IN ('DIURNA','NOCTURNA','MIXTA','POR_TURNOS'));  -- â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ -- ðŸ”§ 5. AREAS: nivel_riesgo_arl -- â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ DO $$ DECLARE r RECORD; BEGIN   FOR r IN (     SELECT conname FROM pg_constraint     WHERE conrelid = 'areas'::regclass       AND contype = 'c'       AND pg_get_constraintdef(oid) ILIKE '%nivel_riesgo_arl%'   ) LOOP     EXECUTE format('ALTER TABLE areas DROP CONSTRAINT IF EXISTS %I', r.conname);   END LOOP; END $$;  UPDATE areas SET nivel_riesgo_arl = 1   WHERE nivel_riesgo_arl IS NOT NULL     AND (nivel_riesgo_arl < 1 OR nivel_riesgo_arl > 5);  ALTER TABLE areas   ADD CONSTRAINT areas_nivel_riesgo_arl_check   CHECK (nivel_riesgo_arl IS NULL OR (nivel_riesgo_arl BETWEEN 1 AND 5));  -- â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ -- ðŸ”§ 6. EMPLOYEES: tipo_contrato -- â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ DO $$ DECLARE r RECORD; BEGIN   FOR r IN (     SELECT conname FROM pg_constraint     WHERE conrelid = 'employees'::regclass       AND contype = 'c'       AND pg_get_constraintdef(oid) ILIKE '%tipo_contrato%'   ) LOOP     EXECUTE format('ALTER TABLE employees DROP CONSTRAINT IF EXISTS %I', r.conname);   END LOOP; END $$;  UPDATE employees SET tipo_contrato = 'INDEFINIDO'   WHERE tipo_contrato IS NOT NULL     AND tipo_contrato NOT IN (       'INDEFINIDO','TERMINO_FIJO','OBRA_LABOR','POR_HORAS','SALARIO_FIJO',       'PRESTACION_SERVICIOS','APRENDIZAJE','OCASIONAL','TEMPORAL'     );  ALTER TABLE employees   ADD CONSTRAINT employees_tipo_contrato_check   CHECK (tipo_contrato IS NULL OR tipo_contrato IN (     'INDEFINIDO','TERMINO_FIJO','OBRA_LABOR','POR_HORAS','SALARIO_FIJO',     'PRESTACION_SERVICIOS','APRENDIZAJE','OCASIONAL','TEMPORAL'   ));  -- â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ -- ðŸ”§ 7. EMPLOYEES: tipo_documento -- â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ DO $$ DECLARE r RECORD; BEGIN   FOR r IN (     SELECT conname FROM pg_constraint     WHERE conrelid = 'employees'::regclass       AND contype = 'c'       AND pg_get_constraintdef(oid) ILIKE '%tipo_documento%'   ) LOOP     EXECUTE format('ALTER TABLE employees DROP CONSTRAINT IF EXISTS %I', r.conname);   END LOOP; END $$;  UPDATE employees SET tipo_documento = 'CC'   WHERE tipo_documento IS NOT NULL     AND tipo_documento NOT IN ('CC','CE','TI','PA','RC','PPT','NIT');  ALTER TABLE employees   ADD CONSTRAINT employees_tipo_documento_check   CHECK (tipo_documento IS NULL OR tipo_documento IN ('CC','CE','TI','PA','RC','PPT','NIT'));  -- â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ -- ðŸ”§ 8. EMPLOYEES: genero -- â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”