”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ DO $$ DECLARE r RECORD; BEGIN   FOR r IN (     SELECT conname FROM pg_constraint     WHERE conrelid = 'employees'::regclass       AND contype = 'c'       AND pg_get_constraintdef(oid) ILIKE '%nivel_cargo%'   ) LOOP     EXECUTE format('ALTER TABLE employees DROP CONSTRAINT IF EXISTS %I', r.conname);   END LOOP; END $$;  UPDATE employees SET nivel_cargo = 'JUNIOR'   WHERE nivel_cargo IS NOT NULL     AND nivel_cargo NOT IN ('JUNIOR','SENIOR','COORDINADOR','SUPERVISOR','JEFE','GERENTE','DIRECTOR');  ALTER TABLE employees   ADD CONSTRAINT employees_nivel_cargo_check   CHECK (nivel_cargo IS NULL OR nivel_cargo IN ('JUNIOR','SENIOR','COORDINADOR','SUPERVISOR','JEFE','GERENTE','DIRECTOR'));  -- â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ -- ðŸ”§ 11. EMPLOYEES: afp_tipo -- â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ DO $$ DECLARE r RECORD; BEGIN   FOR r IN (     SELECT conname FROM pg_constraint     WHERE conrelid = 'employees'::regclass       AND contype = 'c'       AND pg_get_constraintdef(oid) ILIKE '%afp_tipo%'   ) LOOP     EXECUTE format('ALTER TABLE employees DROP CONSTRAINT IF EXISTS %I', r.conname);   END LOOP; END $$;  UPDATE employees SET afp_tipo = 'RAZON'   WHERE afp_tipo IS NOT NULL     AND afp_tipo NOT IN ('RAZON','PRIMAPROMEDIO');  ALTER TABLE employees   ADD CONSTRAINT employees_afp_tipo_check   CHECK (afp_tipo IS NULL OR afp_tipo IN ('RAZON','PRIMAPROMEDIO'));  -- â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ -- ðŸ”§ 12. EMPLOYEES: jornada_tipo -- â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ DO $$ DECLARE r RECORD; BEGIN   FOR r IN (     SELECT conname FROM pg_constraint     WHERE conrelid = 'employees'::regclass       AND contype = 'c'       AND pg_get_constraintdef(oid) ILIKE '%jornada_tipo%'   ) LOOP     EXECUTE format('ALTER TABLE employees DROP CONSTRAINT IF EXISTS %I', r.conname);   END LOOP; END $$;  ALTER TABLE employees ADD COLUMN IF NOT EXISTS jornada_tipo VARCHAR(20) DEFAULT 'DIURNA';  UPDATE employees SET jornada_tipo = 'DIURNA'   WHERE jornada_tipo IS NOT NULL     AND jornada_tipo NOT IN ('DIURNA','NOCTURNA','MIXTA','POR_TURNOS');  ALTER TABLE employees   ADD CONSTRAINT employees_jornada_tipo_check   CHECK (jornada_tipo IS NULL OR jornada_tipo IN ('DIURNA','NOCTURNA','MIXTA','POR_TURNOS'));  -- â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ -- ðŸ”§ 13. EMPLOYEES: nivel_riesgo_arl -- â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ DO $$ DECLARE r RECORD; BEGIN   FOR r IN (     SELECT conname FROM pg_constraint     WHERE conrelid = 'employees'::regclass       AND contype = 'c'       AND pg_get_constraintdef(oid) ILIKE '%nivel_riesgo_arl%'   ) LOOP     EXECUTE format('ALTER TABLE employees DROP CONSTRAINT IF EXISTS %I', r.conname);   END LOOP; END $$;  UPDATE employees SET nivel_riesgo_arl = 1   WHERE nivel_riesgo_arl IS NOT NULL     AND (nivel_riesgo_arl < 1 OR nivel_riesgo_arl > 5);  ALTER TABLE employees   ADD CONSTRAINT employees_nivel_riesgo_arl_check   CHECK (nivel_riesgo_arl IS NULL OR (nivel_riesgo_arl BETWEEN 1 AND 5));  -- â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ -- ðŸ”§ 14. EMPLOYEES: nivel_educacion -- â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ DO $$ DECLARE r RECORD; BEGIN   FOR r IN (     SELECT conname FROM pg_constraint     WHERE conrelid = 'employees'::regclass       AND contype = 'c'       AND pg_get_constraintdef(oid) ILIKE '%nivel_educacion%'   ) LOOP     EXECUTE format('ALTER TABLE employees DROP CONSTRAINT IF EXISTS %I', r.conname);   END LOOP; END $$;  UPDATE employees SET nivel_educacion = NULL   WHERE nivel_educacion IS NOT NULL     AND nivel_educacion NOT IN ('PRIMARIA','BACHILLERATO','TECNICO','TECNOLOGO','PREGRADO','ESPECIALIZACION','MAESTRIA','DOCTORADO','NINGUNO');  ALTER TABLE employees   ADD CONSTRAINT employees_nivel_educacion_check   CHECK (nivel_educacion IS NULL OR nivel_educacion IN ('PRIMARIA','BACHILLERATO','TECNICO','TECNOLOGO','PREGRADO','ESPECIALIZACION','MAESTRIA','DOCTORADO','NINGUNO'));  -- â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ -- ðŸ”§ 15. SHIFT_TEMPLATES: shift_kind -- â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ DO $$ DECLARE r RECORD; BEGIN   FOR r IN (     SELECT conname FROM pg_constraint     WHERE conrelid = 'shift_templates'::regclass       AND contype = 'c'       AND pg_get_constraintdef(oid) ILIKE '%shift_kind%'   ) LOOP     EXECUTE format('ALTER TABLE shift_templates DROP CONSTRAINT IF EXISTS %I', r.conname);   END LOOP; END $$;  UPDATE shift_templates SET shift_kind = 'STANDARD'   WHERE shift_kind IS NOT NULL     AND shift_kind NOT IN ('STANDARD','PARTIDO','ROTATIVO','NOCTURNO','DISPONIBILIDAD','CUSTOM');  ALTER TABLE shift_templates   ADD CONSTRAINT shift_templates_shift_kind_check   CHECK (shift_kind IS NULL OR shift_kind IN ('STANDARD','PARTIDO','ROTATIVO','NOCTURNO','DISPONIBILIDAD','CUSTOM'));  -- â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ -- ðŸ”§ 16. ABSENCES: tipo -- â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ DO $$ DECLARE r RECORD; BEGIN   FOR r IN (     SELECT conname FROM pg_constraint     WHERE conrelid = 'absences'::regclass       AND contype = 'c'       AND pg_get_constraintdef(oid) ILIKE '%tipo%'   ) LOOP     EXECUTE format('ALTER TABLE absences DROP CONSTRAINT IF EXISTS %I', r.conname);   END LOOP; END $$;  ALTER TABLE absences   ADD CONSTRAINT absences_tipo_check   CHECK (tipo IN (     'vacaciones','incapacidad','licencia','suspension',     'licencia_luto','licencia_paternidad','licencia_menstrual',     'dia_familia','permiso_sindical','calamidad'   ));  -- â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ -- ðŸ§ª 17. TESTS AUTOMÃTICOS: simular inserciones -- â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ DO $$ DECLARE   v_tenant_id UUID;   v_test_areas INT := 0;   v_test_pass INT := 0;   v_test_fail INT := 0;   v_contrato TEXT;   v_modo TEXT;   v_jornada TEXT;   v_nivel INT; BEGIN   -- Buscar un tenant existente para los tests   SELECT id INTO v_tenant_id FROM tenants LIMIT 1;    IF v_tenant_id IS NULL THEN     RAISE NOTICE 'âš ï¸  No hay tenants creados. Los tests de inserciÃ³n se saltarÃ¡n. Crea al menos un tenant para validar.';     RETURN;   END IF;    RAISE NOTICE 'â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•';   RAISE NOTICE 'ðŸ§ª TESTS DE INSERCIÃ“N â€” usando tenant: %', v_tenant_id;   RAISE NOTICE 'â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•';    -- Test los 9 tipos de contrato Ã— modos de operaciÃ³n Ã— jornadas   FOREACH v_contrato IN ARRAY ARRAY[     'INDEFINIDO','TERMINO_FIJO','OBRA_LABOR','POR_HORAS','SALARIO_FIJO',     'PRESTACION_SERVICIOS','APRENDIZAJE','OCASIONAL','TEMPORAL'   ] LOOP     FOREACH v_modo IN ARRAY ARRAY['OFICINA', '24_7'] LOOP       FOREACH v_jornada IN ARRAY ARRAY['DIURNA','NOCTURNA','MIXTA','POR_TURNOS'] LOOP         FOREACH v_nivel IN ARRAY ARRAY[1, 2, 3, 4, 5] LOOP           v_test_areas := v_test_areas + 1;           BEGIN             INSERT INTO areas (               tenant_id, nombre, valor_hora_default,               tipo_contrato_default, tipo_contrato_predominante,               modo_operacion, jornada_tipo, nivel_riesgo_arl,               dias_trabajo, dias_descanso_default, dias_descanso,               horas_extras_max_dia, horas_extras_max_semana,               descanso_min_entre_jornadas, duracion_jornada_horas,               color, paga_auxilio_transporte, break_minutos             ) VALUES (               v_tenant_id,               'TEST_AREA_' || v_contrato || '_' || v_modo || '_' || v_jornada || '_ARL' || v_nivel,               12500.00,               v_contrato, v_contrato,               v_modo, v_jornada, v_nivel,               CASE WHEN v_modo = '24_7' THEN ARRAY[1,2,3,4,5,6,7] ELSE ARRAY[1,2,3,4,5] END,               1, 1, 2, 12, 9, 8,               '#6366f1', true, 0             );             v_test_pass := v_test_pass + 1;             -- Limpiar inmediatamente             DELETE FROM areas WHERE nombre LIKE 'TEST_AREA_%';           EXCEPTION WHEN OTHERS THEN             v_test_fail := v_test_fail + 1;             RAISE NOTICE 'âŒ FAIL: %, modo=%, jornada=%, arl=% â†’ %',               v_contrato, v_modo, v_jornada, v_nivel, SQLERRM;           END;         END LOOP;       END LOOP;     END LOOP;   END LOOP;    RAISE NOTICE 'â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•';   RAISE NOTICE 'ðŸ“Š RESULTADO: % intentos Â· âœ… % pasaron Â· âŒ % fallaron',     v_test_areas, v_test_pass, v_test_fail;   RAISE NOTICE 'â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•'; END $$;  -- â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ -- ðŸ§ª 18. TESTS DE TIPOS DE DOCUMENTO Y GÃ‰NERO -- â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ DO $$ DECLARE   v_tenant_id UUID;   v_emp_id UUID;   v_pass INT := 0;   v_fail INT := 0;   v_total INT := 0;   v_doc TEXT;   v_gen TEXT;   v_est TEXT;   v_niv TEXT;   v_tipo TEXT; BEGIN   SELECT id INTO v_tenant_id FROM tenants LIMIT 1;   IF v_tenant_id IS NULL THEN RETURN; END IF;    RAISE NOTICE 'â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•';   RAISE NOTICE 'ðŸ§ª TESTS DE EMPLEADOS â€” combinaciones de catÃ¡logos';   RAISE NOTICE 'â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•';    FOREACH v_doc IN ARRAY ARRAY['CC','CE','TI','PA','PPT','NIT'] LOOP     FOREACH v_gen IN ARRAY ARRAY['M','F','OTRO','PREFIERO_NO_DECIR'] LOOP       FOREACH v_est IN ARRAY ARRAY['SOLTERO','CASADO','UNION_LIBRE','DIVORCIADO','VIUDO','SEPARADO'] LOOP         FOREACH v_niv IN ARRAY ARRAY['JUNIOR','SENIOR','COORDINADOR','SUPERVISOR','JEFE','GERENTE','DIRECTOR'] LOOP           FOREACH v_tipo IN ARRAY ARRAY['INDEFINIDO','TERMINO_FIJO','OBRA_LABOR','POR_HORAS','SALARIO_FIJO','PRESTACION_SERVICIOS','APRENDIZAJE','OCASIONAL','TEMPORAL'] LOOP             v_total := v_total + 1;             BEGIN               INSERT INTO employees (tenant_id, cedula, nombre, cargo, valor_hora, tipo_contrato, tipo_documento, genero, estado_civil, nivel_cargo, nivel_riesgo_arl)               VALUES (v_tenant_id, 'TEST' || v_total::TEXT, 'Test ' || v_total::TEXT, 'Cargo Test', 12500, v_tipo, v_doc, v_gen, v_est, v_niv, 1)               RETURNING id INTO v_emp_id;               v_pass := v_pass + 1;               DELETE FROM employees WHERE id = v_emp_id;             EXCEPTION WHEN OTHERS THEN               v_fail := v_fail + 1;               RAISE NOTICE 'âŒ FAIL: doc=%, gen=%, est=%, niv=%, tipo=% â†’ %',                 v_doc, v_gen, v_est, v_niv, v_tipo, SQLERRM;             END;           END LOOP;         END LOOP;       END LOOP;     END LOOP;   END LOOP;    RAISE NOTICE 'â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•';   RAISE NOTICE 'ðŸ“Š EMPLEADOS: % intentos Â· âœ… % pasaron Â· âŒ % fallaron',     v_total, v_pass, v_fail;   RAISE NOTICE 'â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•'; END $$;  -- â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ -- ðŸ§¹ LIMPIEZA: borrar funciÃ³n helper temporal -- â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ DROP FUNCTION IF EXISTS recreate_check_constraint(TEXT, TEXT, TEXT);  -- Mensaje final DO $$ BEGIN   RAISE NOTICE '';   RAISE NOTICE 'âœ… MIGRACIÃ“N COMPLETADA';   RAISE NOTICE '   Todos los CHECK constraints han sido actualizados.';   RAISE NOTICE '   Datos huÃ©rfanos normalizados.';   RAISE NOTICE '   Si viste âŒ FAIL arriba, revisa el log para detalles.'; END $$;

-- === FILE: add_24_7_night_split.sql === --
-- ============================================================ -- ChronosWork â€” Agregar modo_operacion '24_7_NIGHT_SPLIT' -- Ejecutar en Supabase SQL Editor -- ============================================================ -- Este script actualiza el constraint de modo_operacion para incluir -- el nuevo valor '24_7_NIGHT_SPLIT', que permite Ã¡reas 24/7 con gestiÃ³n -- separada del turno nocturno. -- ============================================================  -- Eliminar constraint existente ALTER TABLE areas DROP CONSTRAINT IF EXISTS areas_modo_operacion_check;  -- Recrear constraint con el nuevo valor ALTER TABLE areas   ADD CONSTRAINT areas_modo_operacion_check   CHECK (modo_operacion IS NULL OR modo_operacion IN ('OFICINA', '24_7', '24_7_NIGHT_SPLIT'));  -- Verificar que el constraint se creÃ³ correctamente DO $$ DECLARE v_count INT; BEGIN   SELECT COUNT(*) INTO v_count   FROM information_schema.table_constraints   WHERE table_name = 'areas'     AND constraint_name = 'areas_modo_operacion_check';    IF v_count = 1 THEN     RAISE NOTICE 'Constraint areas_modo_operacion_check actualizado exitosamente';   ELSE     RAISE EXCEPTION 'Error: no se pudo crear el constraint';   END IF; END $$;

-- === FILE: add_headcount_dia_areas.sql === --
-- ============================================================ -- ChronosWork â€” MigraciÃ³n 007: Headcount objetivo por dÃ­a + hora inicio -- Ejecutar en Supabase SQL Editor -- ============================================================ -- Permite a la empresa decir, por Ã¡rea, CUÃNTAS personas quiere -- programar por dÃ­a (mÃ­nimo/piso y mÃ¡ximo/objetivo) y a quÃ© hora -- arranca el primer turno diurno. El algoritmo v5 usa la curva de -- demanda como FORMA para repartir ese headcount entre las horas. -- ============================================================  ALTER TABLE areas   ADD COLUMN IF NOT EXISTS min_empleados_dia  INT,   ADD COLUMN IF NOT EXISTS max_empleados_dia  INT,   ADD COLUMN IF NOT EXISTS hora_inicio_dia    TIME DEFAULT '04:00',   ADD COLUMN IF NOT EXISTS hora_fin_dia       TIME DEFAULT '22:00';  COMMENT ON COLUMN areas.min_empleados_dia IS   'MÃ­nimo de personas DISTINTAS a programar en el dÃ­a (incluye noche).    Es un PISO: si no se alcanza con la capacidad disponible, el dÃ­a se deja    sin cubrir (vacÃ­o completo) y se avisa, en vez de dejar huecos parciales.    NULL = sin piso (el algoritmo cubre lo que pueda).';  COMMENT ON COLUMN areas.max_empleados_dia IS   'MÃ¡ximo de personas DISTINTAS a programar en el dÃ­a (incluye noche).    Funciona como TECHO y como OBJETIVO de headcount: el algoritmo intenta    llegar a este nÃºmero repartiÃ©ndolo segÃºn la curva de demanda (mÃ¡s gente    en picos, menos en valles) y nunca lo supera.    NULL = sin techo (usa la curva absoluta como antes).';  COMMENT ON COLUMN areas.hora_inicio_dia IS   'Hora a la que puede empezar el primer turno diurno. Default 04:00.    El algoritmo no coloca turnos diurnos antes de esta hora.';  COMMENT ON COLUMN areas.hora_fin_dia IS   'Hora a la que debe TERMINAR como mÃ¡ximo el Ãºltimo turno diurno (cierre de    oficina). Default 22:00. En Ã¡reas de oficina (ej. 08:00-18:00) ningÃºn turno    diurno se extiende mÃ¡s allÃ¡ de esta hora. En Ã¡reas 24/7 se ignora (la noche    manda la cobertura nocturna).';  -- Backfill suave: a las Ã¡reas 24/7 sin objetivo, dejarlo NULL (curva absoluta). -- hora_inicio_dia / hora_fin_dia toman su default para filas existentes. UPDATE areas SET hora_inicio_dia = COALESCE(hora_inicio_dia, '04:00'),     hora_fin_dia    = COALESCE(hora_fin_dia, '22:00');

-- === FILE: add_shift_breaks_detail.sql === --
-- ============================================================ -- ChronosWork â€” Desglose de descansos en `shifts` -- Separa el descanso total en: almuerzo (no pagado) + breaks de 15 min. -- ============================================================ -- Idempotente: se puede correr varias veces sin romper nada. -- Ejecutar en: Supabase SQL Editor -- -- ConvenciÃ³n de horas: --   break_minutes      = minutos que SE DESCUENTAN de las horas netas --                        (= almuerzo_minutos). Lo usan el trigger y la --                        liquidaciÃ³n de prenÃ³mina. NO se toca su semÃ¡ntica. --   almuerzo_minutos   = duraciÃ³n del almuerzo (no pagado). --   breaks_15_count    = nÂº de breaks de 15 min (pagados, informativos; --                        NO se descuentan de las horas netas). -- ============================================================  -- â”€â”€ 1. AÃ±adir columnas de desglose â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ ALTER TABLE shifts   ADD COLUMN IF NOT EXISTS almuerzo_minutos INT DEFAULT 0,   ADD COLUMN IF NOT EXISTS breaks_15_count  INT DEFAULT 0;  -- â”€â”€ 2. Backfill defensivo de filas existentes â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ -- Los turnos viejos guardaban todo el descanso en break_minutes; lo -- interpretamos como almuerzo. Solo backfill donde aÃºn no se ha desglosado. UPDATE shifts SET almuerzo_minutos = COALESCE(break_minutes, 0) WHERE almuerzo_minutos = 0   AND COALESCE(break_minutes, 0) > 0;  -- â”€â”€ 3. Comentarios documentando las columnas â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ COMMENT ON COLUMN shifts.almuerzo_minutos IS   'DuraciÃ³n del almuerzo en minutos (no pagado). Se descuenta de las horas netas vÃ­a break_minutes.'; COMMENT ON COLUMN shifts.breaks_15_count IS   'Cantidad de breaks de 15 minutos del turno (pagados, informativos). No se descuentan de horas netas.';  -- â”€â”€ 4. VerificaciÃ³n final â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ DO $$ DECLARE   v_count INT; BEGIN   SELECT COUNT(*) INTO v_count   FROM information_schema.columns   WHERE table_name = 'shifts'     AND column_name IN ('almuerzo_minutos', 'breaks_15_count');    IF v_count = 2 THEN     RAISE NOTICE 'âœ… MigraciÃ³n exitosa: almuerzo_minutos y breaks_15_count estÃ¡n en shifts.';   ELSE     RAISE EXCEPTION 'âŒ Solo se encontraron % columnas de las 2 esperadas.', v_count;   END IF; END $$;

-- === FILE: add_shift_descansos.sql === --
-- ============================================================ -- ChronosWork â€” ProgramaciÃ³n de descansos con horarios reales -- Almacena los descansos (breaks y almuerzo) de cada turno con su -- hora exacta, y la polÃ­tica de descansos configurable por Ã¡rea. -- ============================================================ -- Idempotente: se puede correr varias veces sin romper nada. -- Ejecutar en: Supabase SQL Editor -- Prerequisito: add_shift_breaks_detail.sql ya aplicado. -- ============================================================  -- â”€â”€ 1. Columna de descansos detallados en cada turno â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ -- Estructura: array de objetos --   [{ "tipo": "BREAK"|"ALMUERZO", "inicio": "HH:MM", "minutos": 15 }, ...] ALTER TABLE shifts   ADD COLUMN IF NOT EXISTS descansos JSONB DEFAULT '[]'::jsonb;  -- â”€â”€ 2. PolÃ­tica de descansos por Ã¡rea â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ -- NULL = usar los defaults legales del front (BREAK_POLICY_DEFAULTS_CO). -- Estructura: -- { --   "breakMinutos": 15, --   "almuerzoMinutos": 60,        -- 30 | 45 | 60 --   "gapMinHoras": 1,             -- mÃ­n. horas antes del 1er descanso / entre descansos --   "gapMaxHoras": 3,             -- mÃ¡x. horas antes del 1er descanso / entre descansos --   "reglas": [                   -- nÂº de breaks y almuerzo segÃºn duraciÃ³n del turno --     { "desdeHoras": 0, "breaks": 1, "almuerzo": false }, --     { "desdeHoras": 6, "breaks": 2, "almuerzo": false }, --     { "desdeHoras": 8, "breaks": 1, "almuerzo": true  }, --     { "desdeHoras": 9, "breaks": 2, "almuerzo": true  } --   ] -- } ALTER TABLE areas   ADD COLUMN IF NOT EXISTS break_policy JSONB DEFAULT NULL;  -- â”€â”€ 3. Comentarios â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ COMMENT ON COLUMN shifts.descansos IS   'Descansos del turno con hora exacta: [{tipo:BREAK|ALMUERZO, inicio:HH:MM, minutos}]. El almuerzo (ALMUERZO) se descuenta de horas netas vÃ­a break_minutes; los BREAK son pagados.'; COMMENT ON COLUMN areas.break_policy IS   'PolÃ­tica de descansos configurable por el empleador (duraciÃ³n de breaks/almuerzo, espaciado mÃ­n/mÃ¡x y reglas por horas). NULL = defaults legales Colombia.';  -- â”€â”€ 4. VerificaciÃ³n final â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ DO $$ DECLARE   v_shifts INT;   v_areas  INT; BEGIN   SELECT COUNT(*) INTO v_shifts FROM information_schema.columns    WHERE table_name = 'shifts' AND column_name = 'descansos';   SELECT COUNT(*) INTO v_areas FROM information_schema.columns    WHERE table_name = 'areas' AND column_name = 'break_policy';    IF v_shifts = 1 AND v_areas = 1 THEN     RAISE NOTICE 'âœ… MigraciÃ³n exitosa: shifts.descansos y areas.break_policy listos.';   ELSE     RAISE EXCEPTION 'âŒ Faltan columnas (shifts.descansos=% , areas.break_policy=%).', v_shifts, v_areas;   END IF; END $$;

-- === FILE: rbac_expansion.sql === --
-- ============================================================ -- ChronosWork â€” ExpansiÃ³n RBAC Multi-tenant -- Sistema de Control de Acceso Basado en Roles (4 niveles) -- ============================================================ -- Idempotente: se puede ejecutar varias veces sin romper nada. -- Ejecutar en: Supabase SQL Editor -- -- Roles implementados: --   SaaS_Admin       â†’ tabla platform_admins (ya existente) --   Super_Admin      â†’ tenant_users.rol = 'super_admin' --   Coordinador_Adminâ†’ tenant_users.rol = 'coordinator' --   Empleado         â†’ tenant_users.rol = 'empleado' (NUEVO) -- ============================================================  -- â”€â”€ SECCIÃ“N 1: Ampliar rol en tenant_users â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€  -- Eliminar el CHECK constraint antiguo y reemplazarlo con uno que incluye 'empleado' DO $$ DECLARE   v_constraint_name TEXT; BEGIN   SELECT constraint_name INTO v_constraint_name   FROM information_schema.table_constraints   WHERE table_name = 'tenant_users'     AND constraint_type = 'CHECK'     AND constraint_name ILIKE '%rol%';    IF v_constraint_name IS NOT NULL THEN     EXECUTE 'ALTER TABLE tenant_users DROP CONSTRAINT IF EXISTS ' || quote_ident(v_constraint_name);   END IF; END $$;  ALTER TABLE tenant_users   DROP CONSTRAINT IF EXISTS tenant_users_rol_check;  ALTER TABLE tenant_users   ADD CONSTRAINT tenant_users_rol_check   CHECK (rol IN ('super_admin', 'admin', 'coordinator', 'empleado'));  COMMENT ON COLUMN tenant_users.rol IS   'super_admin=DueÃ±o empresa | admin=sinÃ³nimo coordinator | coordinator=Programador turnos | empleado=Colaborador';  -- â”€â”€ SECCIÃ“N 2: Vincular empleado con su cuenta Auth â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€  -- Agregar auth_user_id a employees (nullable: no todos tienen cuenta) ALTER TABLE employees   ADD COLUMN IF NOT EXISTS auth_user_id UUID REFERENCES auth.users(id) ON DELETE SET NULL;  CREATE UNIQUE INDEX IF NOT EXISTS idx_employees_auth_user   ON employees(auth_user_id)   WHERE auth_user_id IS NOT NULL;  COMMENT ON COLUMN employees.auth_user_id IS   'UUID de auth.users. Se llena al provisionar cuenta de acceso al empleado.';  -- â”€â”€ SECCIÃ“N 3: Tabla subscriptions â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€  CREATE TABLE IF NOT EXISTS subscriptions (   id          UUID PRIMARY KEY DEFAULT uuid_generate_v4(),   tenant_id   UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,   plan_type   VARCHAR(20) NOT NULL DEFAULT 'mensual'               CHECK (plan_type IN ('mensual', 'trimestral', 'semestral', 'anual')),   status      VARCHAR(20) NOT NULL DEFAULT 'trialing'               CHECK (status IN ('active', 'trialing', 'past_due', 'canceled')),   starts_at   TIMESTAMPTZ NOT NULL DEFAULT NOW(),   expires_at  TIMESTAMPTZ NOT NULL DEFAULT (NOW() + INTERVAL '30 days'),   notas       TEXT,   created_at  TIMESTAMPTZ DEFAULT NOW(),   updated_at  TIMESTAMPTZ DEFAULT NOW(),   UNIQUE(tenant_id) );  CREATE INDEX IF NOT EXISTS idx_subscriptions_tenant ON subscriptions(tenant_id); CREATE INDEX IF NOT EXISTS idx_subscriptions_status ON subscriptions(status, expires_at);  COMMENT ON TABLE subscriptions IS   'Detalle de suscripciones SaaS por tenant. Gestionado exclusivamente por el SaaS_Admin.';  -- Trigger para updated_at automÃ¡tico en subscriptions CREATE OR REPLACE FUNCTION update_subscriptions_updated_at() RETURNS TRIGGER AS $$ BEGIN   NEW.updated_at = NOW();   RETURN NEW; END; $$ LANGUAGE plpgsql;  DROP TRIGGER IF EXISTS trg_subscriptions_updated_at ON subscriptions; CREATE TRIGGER trg_subscriptions_updated_at   BEFORE UPDATE ON subscriptions   FOR EACH ROW EXECUTE FUNCTION update_subscriptions_updated_at();  -- Migrar tenants existentes a la tabla subscriptions si aÃºn no tienen registro INSERT INTO subscriptions (tenant_id, plan_type, status, starts_at, expires_at) SELECT   t.id,   CASE     WHEN t.plan = 'start'      THEN 'mensual'     WHEN t.plan = 'scale'      THEN 'trimestral'     WHEN t.plan = 'enterprise' THEN 'anual'     ELSE 'mensual'   END,   CASE     WHEN t.suscripcion_activa = true AND t.plan_vigente_hasta > NOW() THEN 'active'     WHEN t.suscripcion_activa = true THEN 'trialing'     ELSE 'canceled'   END,   t.created_at,   COALESCE(t.plan_vigente_hasta, NOW() + INTERVAL '30 days') FROM tenants t WHERE NOT EXISTS (   SELECT 1 FROM subscriptions s WHERE s.tenant_id = t.id );  -- â”€â”€ SECCIÃ“N 4: RLS para subscriptions â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€  ALTER TABLE subscriptions ENABLE ROW LEVEL SECURITY;  -- Solo platform_admin ve y modifica todas las suscripciones DROP POLICY IF EXISTS "subscriptions_saas_admin_all" ON subscriptions; CREATE POLICY "subscriptions_saas_admin_all" ON subscriptions   FOR ALL USING (is_platform_admin());  -- Tenant puede ver su propia suscripciÃ³n DROP POLICY IF EXISTS "subscriptions_tenant_select" ON subscriptions; CREATE POLICY "subscriptions_tenant_select" ON subscriptions   FOR SELECT USING (tenant_id = auth_tenant_id());  -- â”€â”€ SECCIÃ“N 5: Funciones helper de rol â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€  -- Obtener el rol del usuario autenticado dentro de su tenant CREATE OR REPLACE FUNCTION auth_user_role() RETURNS TEXT AS $$   SELECT rol FROM tenant_users WHERE user_id = auth.uid() LIMIT 1; $$ LANGUAGE sql STABLE SECURITY DEFINER;  -- Verificar si el usuario es Super_Admin de su empresa CREATE OR REPLACE FUNCTION is_super_admin() RETURNS BOOLEAN AS $$   SELECT EXISTS (     SELECT 1 FROM tenant_users     WHERE user_id = auth.uid() AND rol = 'super_admin'   ); $$ LANGUAGE sql STABLE SECURITY DEFINER;  -- Verificar si el usuario es Coordinador de su empresa CREATE OR REPLACE FUNCTION is_coordinator() RETURNS BOOLEAN AS $$   SELECT EXISTS (     SELECT 1 FROM tenant_users     WHERE user_id = auth.uid() AND rol IN ('coordinator', 'admin')   ); $$ LANGUAGE sql STABLE SECURITY DEFINER;  -- Verificar si el usuario es un Empleado (colaborador) CREATE OR REPLACE FUNCTION is_employee_role() RETURNS BOOLEAN AS $$   SELECT EXISTS (     SELECT 1 FROM tenant_users     WHERE user_id = auth.uid() AND rol = 'empleado'   ); $$ LANGUAGE sql STABLE SECURITY DEFINER;  -- Verificar si el usuario es admin operativo (super_admin o coordinator) CREATE OR REPLACE FUNCTION is_operational_admin() RETURNS BOOLEAN AS $$   SELECT EXISTS (     SELECT 1 FROM tenant_users     WHERE user_id = auth.uid() AND rol IN ('super_admin', 'admin', 'coordinator')   ); $$ LANGUAGE sql STABLE SECURITY DEFINER;  -- Obtener el employee_id del empleado autenticado CREATE OR REPLACE FUNCTION auth_employee_id() RETURNS UUID AS $$   SELECT id FROM employees WHERE auth_user_id = auth.uid() LIMIT 1; $$ LANGUAGE sql STABLE SECURITY DEFINER;  -- â”€â”€ SECCIÃ“N 6: RLS actualizado para rol Empleado â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€  -- ---- employees: el empleado puede leer solo su propio registro ---- DROP POLICY IF EXISTS "employees_select" ON employees; CREATE POLICY "employees_select" ON employees   FOR SELECT USING (     -- Admins ven todos los de su tenant     (tenant_id = auth_tenant_id() AND is_operational_admin())     -- Platform admin ve todos     OR is_platform_admin()     -- Empleado ve solo su propio registro     OR auth_user_id = auth.uid()   );  -- Empleados no pueden insertar/actualizar/eliminar empleados -- (ya existÃ­an las policies restrictivas, se dejan igual)  -- ---- absences: el empleado ve solo sus novedades ---- DROP POLICY IF EXISTS "absences_select" ON absences; CREATE POLICY "absences_select" ON absences   FOR SELECT USING (     -- Admins ven todas las de su tenant     (tenant_id = auth_tenant_id() AND is_operational_admin())     -- Platform admin ve todas     OR is_platform_admin()     -- Empleado ve solo las suyas: join via employees.auth_user_id     OR employee_id = auth_employee_id()   );  -- Empleado NO puede crear/modificar/eliminar novedades (solo leer las suyas) DROP POLICY IF EXISTS "absences_insert" ON absences; CREATE POLICY "absences_insert" ON absences   FOR INSERT WITH CHECK (     tenant_id = auth_tenant_id() AND is_operational_admin()   );  DROP POLICY IF EXISTS "absences_delete" ON absences; CREATE POLICY "absences_delete" ON absences   FOR DELETE USING (     tenant_id = auth_tenant_id() AND is_operational_admin()   );  -- ---- shifts: el empleado ve solo sus turnos ---- DROP POLICY IF EXISTS "shifts_select" ON shifts; CREATE POLICY "shifts_select" ON shifts   FOR SELECT USING (     -- Admins ven todos los de su tenant     (tenant_id = auth_tenant_id() AND is_operational_admin())     -- Platform admin ve todos     OR is_platform_admin()     -- Empleado ve solo los suyos: join via employees.auth_user_id     OR employee_id = auth_employee_id()   );  -- Empleado NO puede crear/modificar/eliminar turnos DROP POLICY IF EXISTS "shifts_insert" ON shifts; CREATE POLICY "shifts_insert" ON shifts   FOR INSERT WITH CHECK (     tenant_id = auth_tenant_id() AND is_operational_admin()   );  DROP POLICY IF EXISTS "shifts_update" ON shifts; CREATE POLICY "shifts_update" ON shifts   FOR UPDATE USING (     tenant_id = auth_tenant_id() AND is_operational_admin()   );  DROP POLICY IF EXISTS "shifts_delete" ON shifts; CREATE POLICY "shifts_delete" ON shifts   FOR DELETE USING (     tenant_id = auth_tenant_id() AND is_operational_admin()   );  -- â”€â”€ SECCIÃ“N 7: RPC â€” Perfil completo del empleado autenticado â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€  CREATE OR REPLACE FUNCTION get_my_employee_profile() RETURNS JSONB AS $$ DECLARE   v_employee_id UUID;   v_result JSONB; BEGIN   -- Solo disponible para rol 'empleado'   IF NOT is_employee_role() THEN     RAISE EXCEPTION 'ACCESS_DENIED: Esta funciÃ³n es exclusiva para colaboradores.';   END IF;    SELECT id INTO v_employee_id FROM employees WHERE auth_user_id = auth.uid();    IF v_employee_id IS NULL THEN     RAISE EXCEPTION 'EMPLOYEE_NOT_FOUND: No se encontrÃ³ el perfil del empleado autenticado.';   END IF;    SELECT jsonb_build_object(     'employee', row_to_json(e.*),     'shifts', (       SELECT jsonb_agg(row_to_json(s.*) ORDER BY s.start_time DESC)       FROM shifts s       WHERE s.employee_id = v_employee_id         AND s.start_time >= NOW() - INTERVAL '60 days'     ),     'absences', (       SELECT jsonb_agg(row_to_json(a.*) ORDER BY a.fecha_inicio DESC)       FROM absences a       WHERE a.employee_id = v_employee_id     )   )   INTO v_result   FROM employees e   WHERE e.id = v_employee_id;    RETURN v_result; END; $$ LANGUAGE plpgsql STABLE SECURITY DEFINER;  -- â”€â”€ SECCIÃ“N 8: RPC â€” GestiÃ³n de suscripciones (SaaS_Admin) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€  -- Listar todos los tenants con su suscripciÃ³n (solo platform_admin) CREATE OR REPLACE FUNCTION get_all_tenants_with_subscriptions() RETURNS TABLE (   tenant_id       UUID,   razon_social    VARCHAR,   nit             VARCHAR,   plan            VARCHAR,   activo          BOOLEAN,   sub_plan_type   VARCHAR,   sub_status      VARCHAR,   sub_expires_at  TIMESTAMPTZ,   sub_notas       TEXT,   created_at      TIMESTAMPTZ ) AS $$ BEGIN   IF NOT is_platform_admin() THEN     RAISE EXCEPTION 'ACCESS_DENIED: Solo el administrador de la plataforma puede ver esta informaciÃ³n.';   END IF;    RETURN QUERY   SELECT     t.id,     t.razon_social,     t.nit,     t.plan,     t.activo,     s.plan_type,     s.status,     s.expires_at,     s.notas,     t.created_at   FROM tenants t   LEFT JOIN subscriptions s ON s.tenant_id = t.id   ORDER BY t.created_at DESC; END; $$ LANGUAGE plpgsql STABLE SECURITY DEFINER;  -- Actualizar suscripciÃ³n de un tenant (solo platform_admin) CREATE OR REPLACE FUNCTION update_tenant_subscription(   p_tenant_id   UUID,   p_plan_type   VARCHAR,   p_status      VARCHAR,   p_expires_at  TIMESTAMPTZ,   p_notas       TEXT DEFAULT NULL ) RETURNS TEXT AS $$ BEGIN   IF NOT is_platform_admin() THEN     RAISE EXCEPTION 'ACCESS_DENIED: Solo el administrador de la plataforma puede modificar suscripciones.';   END IF;    -- Actualizar tabla subscriptions   INSERT INTO subscriptions (tenant_id, plan_type, status, expires_at, notas)   VALUES (p_tenant_id, p_plan_type, p_status, p_expires_at, p_notas)   ON CONFLICT (tenant_id) DO UPDATE SET     plan_type  = EXCLUDED.plan_type,     status     = EXCLUDED.status,     expires_at = EXCLUDED.expires_at,     notas      = EXCLUDED.notas;    -- Sincronizar con tabla tenants (para compatibilidad con el sistema existente)   UPDATE tenants SET     plan                = CASE p_plan_type                             WHEN 'mensual'     THEN 'start'                             WHEN 'trimestral'  THEN 'scale'                             WHEN 'semestral'   THEN 'scale'                             WHEN 'anual'       THEN 'enterprise'                             ELSE plan                           END,     suscripcion_activa  = (p_status IN ('active', 'trialing')),     plan_vigente_hasta  = p_expires_at   WHERE id = p_tenant_id;    RETURN 'OK: SuscripciÃ³n actualizada correctamente para tenant ' || p_tenant_id::TEXT; END; $$ LANGUAGE plpgsql SECURITY DEFINER;  -- â”€â”€ SECCIÃ“N 9: RPC â€” Check de suscripciÃ³n activa â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€  -- Retorna si el tenant del usuario autenticado tiene suscripciÃ³n vigente CREATE OR REPLACE FUNCTION check_my_tenant_subscription() RETURNS JSONB AS $$ DECLARE   v_tenant_id UUID;   v_result JSONB; BEGIN   v_tenant_id := auth_tenant_id();    IF v_tenant_id IS NULL THEN     RETURN jsonb_build_object('active', false, 'reason', 'NO_TENANT');   END IF;    SELECT jsonb_build_object(     'active',      t.suscripcion_activa AND t.plan_vigente_hasta > NOW(),     'plan',        t.plan,     'expires_at',  t.plan_vigente_hasta,     'status',      COALESCE(s.status, 'trialing'),     'reason',      CASE                      WHEN NOT t.suscripcion_activa THEN 'SUBSCRIPTION_INACTIVE'                      WHEN t.plan_vigente_hasta <= NOW() THEN 'SUBSCRIPTION_EXPIRED'                      ELSE 'OK'                    END   )   INTO v_result   FROM tenants t   LEFT JOIN subscriptions s ON s.tenant_id = t.id   WHERE t.id = v_tenant_id;    RETURN v_result; END; $$ LANGUAGE plpgsql STABLE SECURITY DEFINER;  -- â”€â”€ SECCIÃ“N 10: RPC â€” Provisionar empleado en DB (sin Auth) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ -- Esta funciÃ³n registra al empleado en tenant_users. -- La creaciÃ³n del usuario Auth se hace desde la Edge Function.  CREATE OR REPLACE FUNCTION link_employee_auth_account(   p_employee_id  UUID,   p_auth_user_id UUID ) RETURNS TEXT AS $$ BEGIN   -- Solo admins operativos de ese tenant pueden vincular cuentas   IF NOT is_operational_admin() THEN     RAISE EXCEPTION 'ACCESS_DENIED: No tiene permisos para provisionar cuentas de empleados.';   END IF;    -- Verificar que el empleado pertenece al tenant del admin que ejecuta   IF NOT EXISTS (     SELECT 1 FROM employees     WHERE id = p_employee_id AND tenant_id = auth_tenant_id()   ) THEN     RAISE EXCEPTION 'EMPLOYEE_NOT_FOUND: El empleado no pertenece a su organizaciÃ³n.';   END IF;    -- Vincular el auth_user_id al empleado   UPDATE employees SET auth_user_id = p_auth_user_id WHERE id = p_employee_id;    -- Crear entrada en tenant_users para el nuevo empleado   INSERT INTO tenant_users (user_id, tenant_id, rol)   VALUES (p_auth_user_id, auth_tenant_id(), 'empleado')   ON CONFLICT (user_id, tenant_id) DO UPDATE SET rol = 'empleado';    RETURN 'OK'; END; $$ LANGUAGE plpgsql SECURITY DEFINER;  -- â”€â”€ FIN DEL SCRIPT â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ -- VerificaciÃ³n post-ejecuciÃ³n: -- SELECT column_name, data_type FROM information_schema.columns --   WHERE table_name = 'employees' AND column_name = 'auth_user_id'; -- SELECT * FROM subscriptions; -- SELECT auth_user_role();

-- === FILE: fix_employee_profile_rpc.sql === --
-- ============================================================ -- ChronosWork â€” Fix RPC get_my_employee_profile -- Mejoras: --   1. Rango de turnos ampliado a 1 aÃ±o (6 meses atrÃ¡s + 6 adelante) --   2. Incluye campo descansos explÃ­citamente en la selecciÃ³n --   3. Agrega resumen_semana_actual al JSON de respuesta --   4. Mantiene compatibilidad total con el frontend existente -- Ejecutar en: Supabase SQL Editor -- Idempotente: CREATE OR REPLACE -- ============================================================  CREATE OR REPLACE FUNCTION get_my_employee_profile() RETURNS JSONB AS $$ DECLARE   v_employee_id  UUID;   v_result       JSONB;   v_week_start   DATE;   v_week_end     DATE; BEGIN   -- Solo disponible para rol 'empleado'   IF NOT is_employee_role() THEN     RAISE EXCEPTION 'ACCESS_DENIED: Esta funciÃ³n es exclusiva para colaboradores.';   END IF;    SELECT id INTO v_employee_id FROM employees WHERE auth_user_id = auth.uid();    IF v_employee_id IS NULL THEN     RAISE EXCEPTION 'EMPLOYEE_NOT_FOUND: No se encontrÃ³ el perfil del empleado autenticado.';   END IF;    -- Semana actual (Lunes a Domingo) en zona Colombia   v_week_start := DATE_TRUNC('week', NOW() AT TIME ZONE 'America/Bogota')::DATE;   v_week_end   := v_week_start + INTERVAL '6 days';    SELECT jsonb_build_object(     -- â”€â”€ Datos del empleado â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€     'employee', row_to_json(e.*),      -- â”€â”€ Todos los turnos del aÃ±o (6 meses atrÃ¡s + 6 meses adelante) â”€â”€â”€â”€â”€â”€â”€â”€     -- Se incluye el campo 'descansos' JSONB explÃ­citamente     'shifts', (       SELECT COALESCE(         jsonb_agg(           jsonb_build_object(             'id',                s.id,             'employee_id',       s.employee_id,             'tenant_id',         s.tenant_id,             'start_time',        s.start_time,             'end_time',          s.end_time,             'shift_type',        s.shift_type,             'periodo',           s.periodo,             'break_minutes',     COALESCE(s.break_minutes, 0),             'descansos',         COALESCE(s.descansos, '[]'::jsonb),             'recargo_porcentaje',COALESCE(s.recargo_porcentaje, 0),             'created_at',        s.created_at           )           ORDER BY s.start_time ASC         ),         '[]'::jsonb       )       FROM shifts s       WHERE s.employee_id = v_employee_id         AND s.start_time >= (NOW() AT TIME ZONE 'America/Bogota' - INTERVAL '6 months')         AND s.start_time <= (NOW() AT TIME ZONE 'America/Bogota' + INTERVAL '6 months')     ),      -- â”€â”€ Novedades (todas) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€     'absences', (       SELECT COALESCE(         jsonb_agg(row_to_json(a.*) ORDER BY a.fecha_inicio DESC),         '[]'::jsonb       )       FROM absences a       WHERE a.employee_id = v_employee_id     ),      -- â”€â”€ Resumen semana actual â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€     'resumen_semana_actual', (       SELECT jsonb_build_object(         'semana_inicio',    v_week_start,         'semana_fin',       v_week_end,         'total_turnos',     COUNT(s.id),         'total_horas_brutas',           COALESCE(SUM(             EXTRACT(EPOCH FROM (s.end_time - s.start_time)) / 3600           ), 0),         'total_horas_netas',           COALESCE(SUM(             GREATEST(0,               EXTRACT(EPOCH FROM (s.end_time - s.start_time)) / 3600               - COALESCE(s.break_minutes, 0) / 60.0             )           ), 0)       )       FROM shifts s       WHERE s.employee_id = v_employee_id         AND (s.start_time AT TIME ZONE 'America/Bogota')::DATE BETWEEN v_week_start AND v_week_end     ),      -- â”€â”€ Resumen mes actual â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€     'resumen_mes', (       SELECT jsonb_build_object(         'total_turnos',      COUNT(s.id),         'total_horas_brutas',           COALESCE(SUM(EXTRACT(EPOCH FROM (s.end_time - s.start_time)) / 3600), 0),         'total_horas_netas',           COALESCE(SUM(             GREATEST(0,               EXTRACT(EPOCH FROM (s.end_time - s.start_time)) / 3600               - COALESCE(s.break_minutes, 0) / 60.0             )           ), 0)       )       FROM shifts s       WHERE s.employee_id = v_employee_id         AND TO_CHAR(s.start_time AT TIME ZONE 'America/Bogota', 'YYYY-MM')             = TO_CHAR(NOW() AT TIME ZONE 'America/Bogota', 'YYYY-MM')     ),      -- â”€â”€ Resumen mes siguiente â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€     'resumen_mes_siguiente', (       SELECT jsonb_build_object(         'total_turnos',      COUNT(s.id),         'total_horas_brutas',           COALESCE(SUM(EXTRACT(EPOCH FROM (s.end_time - s.start_time)) / 3600), 0),         'total_horas_netas',           COALESCE(SUM(             GREATEST(0,               EXTRACT(EPOCH FROM (s.end_time - s.start_time)) / 3600               - COALESCE(s.break_minutes, 0) / 60.0             )           ), 0)       )       FROM shifts s       WHERE s.employee_id = v_employee_id         AND TO_CHAR(s.start_time AT TIME ZONE 'America/Bogota', 'YYYY-MM')             = TO_CHAR((NOW() AT TIME ZONE 'America/Bogota' + INTERVAL '1 month'), 'YYYY-MM')     )   )   INTO v_result   FROM employees e   WHERE e.id = v_employee_id;    RETURN v_result; END; $$ LANGUAGE plpgsql STABLE SECURITY DEFINER;  -- â”€â”€ VerificaciÃ³n â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ -- Para probar (ejecutar como empleado autenticado): -- SELECT get_my_employee_profile(); -- El resultado debe incluir: employee, shifts (array), absences,  -- resumen_semana_actual, resumen_mes, resumen_mes_siguiente

-- === FILE: update_shifts_break.sql === --
-- Script para actualizar la base de datos: AÃ±adir break_minutes -- Este archivo debe ejecutarse manualmente en el SQL Editor de Supabase.  -- 1. AÃ±adir la columna break_minutes a la tabla shifts ALTER TABLE shifts ADD COLUMN IF NOT EXISTS break_minutes INT DEFAULT 0;  -- 2. Actualizar la funciÃ³n del trigger para que descuente los minutos de descanso CREATE OR REPLACE FUNCTION validate_shift_extras() RETURNS TRIGGER AS $$ DECLARE   v_dia_horas DECIMAL;   v_semana_horas DECIMAL;   v_horas_turno DECIMAL;   v_fecha DATE;   v_semana_inicio DATE;   v_semana_fin DATE; BEGIN   -- Calcular horas del turno descontando los minutos de descanso   v_horas_turno := (EXTRACT(EPOCH FROM (NEW.end_time - NEW.start_time)) / 3600) - (COALESCE(NEW.break_minutes, 0) / 60.0);      -- Asegurar que las horas del turno no sean negativas por un error en break_minutes   IF v_horas_turno < 0 THEN     v_horas_turno := 0;   END IF;    v_fecha := DATE(NEW.start_time AT TIME ZONE 'America/Bogota');   v_semana_inicio := DATE_TRUNC('week', v_fecha)::DATE;   v_semana_fin := v_semana_inicio + INTERVAL '6 days';    -- Sumar horas previas del mismo dÃ­a   SELECT COALESCE(SUM((EXTRACT(EPOCH FROM (end_time - start_time)) / 3600) - (COALESCE(break_minutes, 0) / 60.0)), 0)   INTO v_dia_horas   FROM shifts   WHERE employee_id = NEW.employee_id     AND DATE(start_time AT TIME ZONE 'America/Bogota') = v_fecha     AND id != COALESCE(NEW.id, uuid_generate_v4());    -- Sumar horas previas de la misma semana   SELECT COALESCE(SUM((EXTRACT(EPOCH FROM (end_time - start_time)) / 3600) - (COALESCE(break_minutes, 0) / 60.0)), 0)   INTO v_semana_horas   FROM shifts   WHERE employee_id = NEW.employee_id     AND DATE(start_time AT TIME ZONE 'America/Bogota') BETWEEN v_semana_inicio AND v_semana_fin     AND id != COALESCE(NEW.id, uuid_generate_v4());    -- LÃ­mite Diario: 14 horas   IF (v_dia_horas + v_horas_turno) > 14 THEN     RAISE EXCEPTION 'LÃMITE_EXCEDIDO: El turno supera el mÃ¡ximo diario permitido de horas para el empleado.';   END IF;    -- LÃ­mite Semanal: 42 horas (Ley 2101/2021 â€” jornada mÃ¡xima legal en Colombia)   IF (v_semana_horas + v_horas_turno) > 42 THEN     RAISE EXCEPTION 'LÃMITE_SEMANAL_EXCEDIDO: El turno supera el lÃ­mite semanal de 42 horas (Ley 2101/2021).';   END IF;    RETURN NEW; END; $$ LANGUAGE plpgsql;

-- === FILE: rls_rbac_areas.sql === --
-- ============================================================ -- ChronosWork â€” RLS RBAC para tablas de Ã¡reas, templates y demanda -- Actualiza las polÃ­ticas para respetar el modelo de roles: --   - empleado    â†’ solo ve su propia Ã¡rea/asignaciÃ³n --   - coordinator â†’ ve todo en su tenant (operational admin) --   - super_admin â†’ ve todo en su tenant --   - saas_admin  â†’ ve todo (platform_admin) -- -- Ejecutar en: Supabase SQL Editor -- ============================================================  -- â”€â”€ areas: restringir SELECT para empleados â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ DROP POLICY IF EXISTS "areas_select" ON areas; CREATE POLICY "areas_select" ON areas FOR SELECT USING (   tenant_id = auth_tenant_id() AND is_operational_admin()   OR is_platform_admin() );  -- INSERT/UPDATE/DELETE solo para admins operativos DROP POLICY IF EXISTS "areas_insert" ON areas; CREATE POLICY "areas_insert" ON areas FOR INSERT WITH CHECK (   tenant_id = auth_tenant_id() AND is_operational_admin() );  DROP POLICY IF EXISTS "areas_update" ON areas; CREATE POLICY "areas_update" ON areas FOR UPDATE USING (   tenant_id = auth_tenant_id() AND is_operational_admin() );  DROP POLICY IF EXISTS "areas_delete" ON areas; CREATE POLICY "areas_delete" ON areas FOR DELETE USING (   tenant_id = auth_tenant_id() AND is_operational_admin() );  -- â”€â”€ area_employees: empleado solo ve su propia asignaciÃ³n â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ DROP POLICY IF EXISTS "area_employees_select" ON area_employees; CREATE POLICY "area_employees_select" ON area_employees FOR SELECT USING (   tenant_id = auth_tenant_id() AND is_operational_admin()   OR is_platform_admin()   OR employee_id = auth_employee_id()  -- empleado ve su propia Ã¡rea );  DROP POLICY IF EXISTS "area_employees_insert" ON area_employees; CREATE POLICY "area_employees_insert" ON area_employees FOR INSERT WITH CHECK (   tenant_id = auth_tenant_id() AND is_operational_admin() );  DROP POLICY IF EXISTS "area_employees_delete" ON area_employees; CREATE POLICY "area_employees_delete" ON area_employees FOR DELETE USING (   tenant_id = auth_tenant_id() AND is_operational_admin() );  -- â”€â”€ shift_templates: solo admins operativos gestionan â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ DROP POLICY IF EXISTS "shift_templates_select" ON shift_templates; CREATE POLICY "shift_templates_select" ON shift_templates FOR SELECT USING (   tenant_id = auth_tenant_id()   OR is_platform_admin() );  DROP POLICY IF EXISTS "shift_templates_insert" ON shift_templates; CREATE POLICY "shift_templates_insert" ON shift_templates FOR INSERT WITH CHECK (   tenant_id = auth_tenant_id() AND is_operational_admin() );  DROP POLICY IF EXISTS "shift_templates_update" ON shift_templates; CREATE POLICY "shift_templates_update" ON shift_templates FOR UPDATE USING (   tenant_id = auth_tenant_id() AND is_operational_admin() );  DROP POLICY IF EXISTS "shift_templates_delete" ON shift_templates; CREATE POLICY "shift_templates_delete" ON shift_templates FOR DELETE USING (   tenant_id = auth_tenant_id() AND is_operational_admin() );  -- â”€â”€ area_demand_slots: restringir escritura a admins â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ ALTER TABLE area_demand_slots ENABLE ROW LEVEL SECURITY;  DROP POLICY IF EXISTS "area_demand_slots_select" ON area_demand_slots; CREATE POLICY "area_demand_slots_select" ON area_demand_slots FOR SELECT USING (   tenant_id = auth_tenant_id()   OR is_platform_admin() );  DROP POLICY IF EXISTS "area_demand_slots_insert" ON area_demand_slots; CREATE POLICY "area_demand_slots_insert" ON area_demand_slots FOR INSERT WITH CHECK (   tenant_id = auth_tenant_id() AND is_operational_admin() );  DROP POLICY IF EXISTS "area_demand_slots_update" ON area_demand_slots; CREATE POLICY "area_demand_slots_update" ON area_demand_slots FOR UPDATE USING (   tenant_id = auth_tenant_id() AND is_operational_admin() );  DROP POLICY IF EXISTS "area_demand_slots_delete" ON area_demand_slots; CREATE POLICY "area_demand_slots_delete" ON area_demand_slots FOR DELETE USING (   tenant_id = auth_tenant_id() AND is_operational_admin() );

